"use strict";
// Static safety scan for generated plugins. Two layers:
//   1. bytecode: `javap -c -p` over every compiled class, matched against
//      invoked owners/methods (cannot be dodged by source formatting tricks);
//   2. source: heuristics that need string literals / context (paths, UUIDs,
//      name checks feeding privileges, encoded blobs).
// Verdict is decided here, never by the model.

const { execFileSync } = require("child_process");
const fs = require("fs");
const path = require("path");

// [id, regex over javap output, plain-English message]
const BYTECODE_BLOCK = [
  ["exec", /java\/lang\/(Runtime\.exec|ProcessBuilder|ProcessHandle)/, "runs other programs on the server machine"],
  ["network", /java\/net\/(Socket|ServerSocket|DatagramSocket|MulticastSocket|URL\.(openConnection|openStream)|URLConnection|HttpURLConnection|InetAddress\.getByName)|java\/net\/http\/|java\/nio\/channels\/(Socket|ServerSocket|Datagram)Channel|javax\/net\//, "connects to the internet or other machines"],
  ["classload", /java\/lang\/ClassLoader\.defineClass|java\/net\/URLClassLoader|MethodHandles\$Lookup\.defineClass|java\/lang\/invoke\/MethodHandles\$Lookup\.defineHiddenClass/, "loads code at runtime that we can't check"],
  ["unsafe", /sun\/misc\/Unsafe|jdk\/internal\//, "uses unsafe JVM internals"],
  ["exit", /java\/lang\/(System\.exit|Runtime\.(halt|exit))/, "can shut the whole server down"],
  ["jni", /java\/lang\/(System|Runtime)\.load(Library)?:/, "loads native code"],
  ["script", /javax\/script\//, "runs scripts that we can't check"],
  ["nms", /net\/minecraft\/|org\/bukkit\/craftbukkit\//, "reaches into server internals (breaks on updates)"],
];
const BYTECODE_WARN = [
  ["reflection", /java\/lang\/reflect\/(Field|Method|Constructor|AccessibleObject)\.setAccessible|java\/lang\/Class\.(forName|getDeclared)/, "uses reflection"],
  ["op", /setOp:\(Z\)V/, "can change who is a server operator"],
  ["console-dispatch", /org\/bukkit\/(Bukkit|Server)\.dispatchCommand/, "runs server commands"],
  ["perm-attach", /addAttachment:/, "grants permissions at runtime"],
  ["base64", /java\/util\/Base64\$Decoder/, "decodes encoded data"],
];

function scanBytecode(classDir) {
  const findings = [];
  const classes = [];
  (function walk(d) {
    for (const e of fs.readdirSync(d, { withFileTypes: true })) {
      const p = path.join(d, e.name);
      if (e.isDirectory()) walk(p);
      else if (e.name.endsWith(".class")) classes.push(p);
    }
  })(classDir);
  if (!classes.length) return findings;
  let out = "";
  for (let i = 0; i < classes.length; i += 40) {
    out += execFileSync("javap", ["-c", "-p", ...classes.slice(i, i + 40)], { encoding: "utf8", maxBuffer: 64 * 1024 * 1024, timeout: 60000 });
  }
  let current = "";
  for (const line of out.split("\n")) {
    const m = line.match(/^(?:public |final |abstract |private |protected |static )*(?:class|interface|enum|record) ([\w.$]+)/);
    if (m) current = m[1];
    for (const [id, re, msg] of BYTECODE_BLOCK) if (re.test(line)) findings.push({ severity: "block", rule: id, where: current, message: msg, evidence: line.trim().slice(0, 200) });
    for (const [id, re, msg] of BYTECODE_WARN) if (re.test(line)) findings.push({ severity: "warn", rule: id, where: current, message: msg, evidence: line.trim().slice(0, 200) });
  }
  return dedupe(findings);
}

function scanSource(srcFiles) {
  const findings = [];
  const uuidRe = /"[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}"/;
  const absPathRe = /"(\/(etc|root|home|proc|sys|var|tmp|opt|usr|bin|dev)\b[^"]*|[A-Za-z]:\\\\[^"]*|[^"]*\.\.[\/\\][^"]*|~\/[^"]*)"/;
  const nameCheckRe = /getName\(\)\s*\.\s*equals(IgnoreCase)?\s*\(\s*"[^"]+"\s*\)|"[^"]+"\s*\.\s*equals(IgnoreCase)?\s*\([^)]*getName\(\)/;
  const blobRe = /"[A-Za-z0-9+\/=]{200,}"/;
  for (const f of srcFiles) {
    const text = fs.readFileSync(f.abs, "utf8");
    const lines = text.split("\n");
    const privileged = /setOp\s*\(\s*true|addAttachment|dispatchCommand|setPermission/.test(text);
    lines.forEach((l, i) => {
      const at = `${f.rel}:${i + 1}`;
      if (absPathRe.test(l) && /File|Path|Files|FileWriter|FileReader|Stream/.test(l))
        findings.push({ severity: "block", rule: "file-outside", where: at, message: "reads or writes files outside the plugin's own folder", evidence: l.trim().slice(0, 200) });
      if (blobRe.test(l)) findings.push({ severity: "block", rule: "encoded-blob", where: at, message: "contains a large encoded blob (possible hidden payload)", evidence: l.trim().slice(0, 80) + "…" });
      if (uuidRe.test(l)) findings.push({ severity: privileged ? "block" : "warn", rule: "hardcoded-uuid", where: at, message: privileged ? "gives special rights to a hard-coded player" : "contains a hard-coded player ID", evidence: l.trim().slice(0, 200) });
      if (nameCheckRe.test(l) && privileged) findings.push({ severity: "block", rule: "hardcoded-name", where: at, message: "gives special rights to a hard-coded player name", evidence: l.trim().slice(0, 200) });
    });
  }
  return dedupe(findings);
}

// Secrets must never leave the box (the model can read files in its sandbox).
function scanSecrets(allFiles, secrets) {
  const hits = [];
  for (const f of allFiles) {
    let text;
    try { text = fs.readFileSync(f.abs, "utf8"); } catch { continue; }
    if (/sk-ant-[A-Za-z0-9_-]{10,}/.test(text)) hits.push(f.rel);
    else for (const s of secrets) if (s && s.length >= 16 && text.includes(s)) { hits.push(f.rel); break; }
  }
  return hits;
}

