"use strict";
// Nxeon Mod Builder build service.
//
// POST /builds                 {id, prompt, mcVersion, pluginName?, baseBuildId?, changeRequest?} -> 202
// GET  /builds/:id             status + events + result
// GET  /builds/:id/artifact    the plugin .jar
// GET  /builds/:id/source?path=src/main/java/...   one source file (text)
// GET  /builds/:id/source.zip  all source (+ Gradle template) as a zip
// POST /builds/:id/cancel
// GET  /health
//
// Every route except /health needs `Authorization: Bearer $MODBUILDER_API_KEY`.
// AI auth is whatever the Claude CLI finds in the environment:
//   CLAUDE_CODE_OAUTH_TOKEN (owner subscription, testing) or ANTHROPIC_API_KEY
//   (paid API, production). Swapping is a one-line change in the env file.

const http = require("http");
const fs = require("fs");
const path = require("path");
const crypto = require("crypto");
const { spawn, execFileSync } = require("child_process");
const YAML = require("yaml");
const { scanBytecode, scanSource, scanSecrets } = require("./scan");
const P = require("./prompts");

const PORT = int(process.env.PORT, 3000);
const DATA = process.env.MB_DATA || "/data";
const BUILDS = path.join(DATA, "builds");
const TEMPLATE = "/opt/mb/template";
const CP_DIR = "/opt/mb/classpath";
const API_KEY = process.env.MODBUILDER_API_KEY || "";
const MODEL = process.env.MB_MODEL || "sonnet";
const REPAIR_MODEL = process.env.MB_REPAIR_MODEL || MODEL;
const CONCURRENCY = int(process.env.MB_CONCURRENCY, 2);
const MAX_REPAIRS = int(process.env.MB_MAX_REPAIRS, 3);
const BUILD_BUDGET_USD = num(process.env.MB_BUILD_BUDGET_USD, 4);
const CALL_BUDGET_USD = num(process.env.MB_CALL_BUDGET_USD, 2.5);
const BUILD_TIMEOUT_MS = int(process.env.MB_BUILD_TIMEOUT_S, 1200) * 1000;
const CALL_TIMEOUT_MS = int(process.env.MB_CALL_TIMEOUT_S, 600) * 1000;
const MAX_TURNS = int(process.env.MB_MAX_TURNS, 60);
const VERSIONS = (process.env.MB_VERSIONS || "1.21.11").split(/\s+/).filter(Boolean);
const SECRETS = [process.env.CLAUDE_CODE_OAUTH_TOKEN, process.env.ANTHROPIC_API_KEY, API_KEY].filter(Boolean);

function int(v, d) { const n = parseInt(v || "", 10); return Number.isFinite(n) ? n : d; }
function num(v, d) { const n = parseFloat(v || ""); return Number.isFinite(n) ? n : d; }
function now() { return new Date().toISOString(); }
function log(level, msg, meta = {}) { process.stderr.write(JSON.stringify({ ts: now(), level, msg, ...meta }) + "\n"); }

fs.mkdirSync(BUILDS, { recursive: true });

// ---------------------------------------------------------------- state ----
const records = new Map(); // id -> record (also persisted to build.json)
const queue = [];
const running = new Map(); // id -> { child, cancelled }

function dirOf(id) { return path.join(BUILDS, id); }
function save(rec) {
  rec.updatedAt = now();
  const f = path.join(dirOf(rec.id), "build.json");
  fs.writeFileSync(f + ".tmp", JSON.stringify(rec, null, 2));
  fs.renameSync(f + ".tmp", f);
}
function event(rec, stage, message, detail) {
  rec.events.push({ at: now(), stage, message, ...(detail ? { detail: String(detail).slice(0, 4000) } : {}) });
  if (rec.events.length > 400) rec.events.splice(1, rec.events.length - 400);
  save(rec);
}
function setStage(rec, status, message) { rec.status = status; event(rec, status, message); }

// Load persisted builds; anything mid-flight when the service stopped is failed.
for (const id of fs.readdirSync(BUILDS)) {
  try {
    const rec = JSON.parse(fs.readFileSync(path.join(dirOf(id), "build.json"), "utf8"));
    if (!["succeeded", "failed"].includes(rec.status)) {
      rec.status = "failed";
      rec.error = "The build service restarted while this build was running. Please try again.";
      rec.errorCode = "interrupted";
      rec.finishedAt = now();
      rec.events.push({ at: now(), stage: "failed", message: "Interrupted by a service restart" });
      save(rec);
    }
    records.set(id, rec);
  } catch { /* ignore broken dirs */ }
}

// ------------------------------------------------------------- helpers ----
function copyDir(src, dst, filter = () => true) {
  fs.mkdirSync(dst, { recursive: true });
  for (const e of fs.readdirSync(src, { withFileTypes: true })) {
    const s = path.join(src, e.name), d = path.join(dst, e.name);
    if (!filter(s, e)) continue;
    if (e.isDirectory()) copyDir(s, d, filter);
    else if (e.isFile()) fs.copyFileSync(s, d);
  }
}
function listFiles(root, rel = "") {
  const out = [];
  const abs = path.join(root, rel);
  if (!fs.existsSync(abs)) return out;
  for (const e of fs.readdirSync(abs, { withFileTypes: true })) {
    const r = path.posix.join(rel, e.name);
    if (e.isSymbolicLink()) { fs.rmSync(path.join(root, r), { force: true }); continue; }
    if (e.isDirectory()) out.push(...listFiles(root, r));
    else if (e.isFile()) out.push({ rel: r, abs: path.join(root, r), size: fs.statSync(path.join(root, r)).size });
  }
  return out;
}
function rmrf(p) { fs.rmSync(p, { recursive: true, force: true }); }
function childEnv(withAi) {
  const env = { PATH: process.env.PATH, HOME: process.env.HOME || "/home/claude", JAVA_HOME: process.env.JAVA_HOME, LANG: "C.UTF-8" };
  if (withAi) {
    for (const k of ["CLAUDE_CODE_OAUTH_TOKEN", "ANTHROPIC_API_KEY", "ANTHROPIC_BASE_URL"]) if (process.env[k]) env[k] = process.env[k];
    env.DISABLE_AUTOUPDATER = "1";
    env.CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC = "1";
  }
  return env;
}
function run(cmd, args, opts) {
  return new Promise((resolve) => {
    const child = spawn(cmd, args, { cwd: opts.cwd, env: opts.env, stdio: ["ignore", "pipe", "pipe"] });
    if (opts.track) opts.track.child = child;
    let out = "", err = "";
    child.stdout.on("data", (d) => { out += d; if (opts.onStdout) opts.onStdout(d); if (out.length > 8e6) out = out.slice(-4e6); });
    child.stderr.on("data", (d) => { err += d; if (err.length > 2e6) err = err.slice(-1e6); });
    const t = setTimeout(() => { child.kill("SIGKILL"); err += "\n[timeout]"; }, opts.timeout);
    child.on("close", (code, signal) => { clearTimeout(t); resolve({ code, signal, out, err, timedOut: err.endsWith("[timeout]") }); });
    child.on("error", (e) => { clearTimeout(t); resolve({ code: -1, out, err: String(e) }); });
  });
}

// ------------------------------------------------------------ AI calls ----
const SETTINGS = JSON.stringify({
  permissions: {
    deny: ["Bash", "WebFetch", "WebSearch", "Read(//proc/**)", "Read(//etc/**)", "Read(//home/**)", "Read(//opt/**)", "Read(//root/**)", "Read(//run/**)", "Read(//data/**)"],
  },
});

async function callClaude(rec, ctl, ws, prompt, { resume, model }) {
  const args = ["-p", "--output-format", "stream-json", "--verbose",
    "--permission-mode", "acceptEdits",
    "--tools", "Read", "Write", "Edit", "Glob", "Grep",
    "--setting-sources", "", "--settings", SETTINGS, "--strict-mcp-config",
    "--model", model, "--max-turns", String(MAX_TURNS),
    "--max-budget-usd", String(Math.max(0.2, Math.min(CALL_BUDGET_USD, BUILD_BUDGET_USD - rec.costUsd))),
    "--system-prompt", P.systemPrompt(rec.mcVersion)];
  if (resume) args.push("--resume", resume); else args.push("--session-id", rec.sessionId);
  args.push("--", prompt);

  let buf = "", result = null, wroteAny = false;
  const onStdout = (d) => {
    buf += d;
    let i;
    while ((i = buf.indexOf("\n")) >= 0) {
      const line = buf.slice(0, i); buf = buf.slice(i + 1);
      if (!line.trim()) continue;
      let msg; try { msg = JSON.parse(line); } catch { continue; }
      if (msg.type === "assistant" && msg.message && Array.isArray(msg.message.content)) {
        for (const c of msg.message.content) {
          if (c.type !== "tool_use") continue;
          const fp = c.input && (c.input.file_path || c.input.path || "");
          const rel = fp ? path.relative(ws, fp) || fp : "";
          const short = rel.split("/").pop();
          if (c.name === "Write" || c.name === "Edit" || c.name === "MultiEdit") {
            if (!wroteAny && rec.status === "planning") setStage(rec, "coding", "Writing the plugin code");
            wroteAny = true;
            event(rec, rec.status, `${c.name === "Write" ? "Wrote" : "Edited"} ${short}`);
          } else if (c.name === "Read" && short) event(rec, rec.status, `Reading ${short}`);
        }
      } else if (msg.type === "result") result = msg;
    }
  };
  const r = await run("claude", args, { cwd: ws, env: childEnv(true), timeout: CALL_TIMEOUT_MS, onStdout, track: ctl });
  ctl.child = null;
  const cost = result && typeof result.total_cost_usd === "number" ? result.total_cost_usd : 0;
  rec.costUsd = +(rec.costUsd + cost).toFixed(4);
  rec.aiCalls.push({ at: now(), model, costUsd: cost, turns: result ? result.num_turns : null, durationMs: result ? result.duration_ms : null, subtype: result ? result.subtype : null, exit: r.code });
  if (result && result.usage) {
    const u = result.usage;
    rec.tokens.input += (u.input_tokens || 0) + (u.cache_creation_input_tokens || 0) + (u.cache_read_input_tokens || 0);
    rec.tokens.output += u.output_tokens || 0;
  }
  save(rec);
  if (ctl.cancelled) throw fail("cancelled", "Build cancelled.");
  if (!result) {
    log("error", "claude produced no result", { id: rec.id, code: r.code, err: r.err.slice(-2000) });
    const authish = /auth|401|403|login|credit|quota|rate.?limit|overloaded/i.test(r.err);
    throw fail(r.timedOut ? "timeout" : "ai_unavailable", r.timedOut ? "The AI took too long on this one. Try a smaller request." : "The AI builder is unavailable right now. Please try again in a few minutes.", authish ? "AI service error" : r.err.slice(-1500));
  }
  if (result.subtype === "error_max_budget_usd") throw fail("budget", "This build reached its spending cap before finishing. Try a smaller request or split it into two plugins.");
  if (result.is_error && result.subtype !== "error_max_turns") {
    throw fail("ai_unavailable", "The AI builder hit an error. Please try again in a few minutes.", String(result.result || result.subtype).slice(0, 1500));
  }
  return result;
}

function fail(code, message, detail) { const e = new Error(message); e.code = code; e.detail = detail; return e; }

// ------------------------------------------------------- validation/compile
function readSummary(ws) {
  const f = path.join(ws, "modbuilder.json");
  if (!fs.existsSync(f)) return null;
  try { return JSON.parse(fs.readFileSync(f, "utf8")); } catch { return { _invalid: true }; }
}

// Keep the model inside its lane: only src/main/** and modbuilder.json survive,
// Gradle files always come from the pinned template.
function sanitizeWorkspace(ws, rec) {
  for (const f of listFiles(ws)) {
    const ok = f.rel.startsWith("src/main/java/") || f.rel.startsWith("src/main/resources/") || f.rel === "modbuilder.json"
      || f.rel === "build.gradle.kts" || f.rel === "settings.gradle.kts";
    if (!ok) { fs.rmSync(f.abs, { force: true }); event(rec, rec.status, `Removed unexpected file ${f.rel}`); }
  }
  for (const g of ["build.gradle.kts", "settings.gradle.kts"]) fs.copyFileSync(path.join(TEMPLATE, g), path.join(ws, g));
}

function validate(ws, rec) {
  const problems = [];
  const res = path.join(ws, "src/main/resources");
  const ymlPath = path.join(res, "plugin.yml");
  if (fs.existsSync(path.join(res, "paper-plugin.yml"))) problems.push("Use plugin.yml, not paper-plugin.yml: delete src/main/resources/paper-plugin.yml.");
  if (!fs.existsSync(ymlPath)) return { problems: ["src/main/resources/plugin.yml is missing."], yml: null };
  let yml;
  try { yml = YAML.parse(fs.readFileSync(ymlPath, "utf8")); } catch (e) { return { problems: [`plugin.yml is not valid YAML: ${e.message}`], yml: null }; }
  if (!yml || typeof yml !== "object") return { problems: ["plugin.yml is empty."], yml: null };
  if (!/^[A-Za-z0-9_]{1,40}$/.test(String(yml.name || ""))) problems.push("plugin.yml name must be 1-40 letters, digits or underscores.");
  if (!yml.version) problems.push("plugin.yml needs a version.");
  const main = String(yml.main || "");
  if (!/^[a-zA-Z_][\w]*(\.[a-zA-Z_][\w]*)+$/.test(main)) problems.push("plugin.yml main must be a fully-qualified class name.");
  else if (!fs.existsSync(path.join(ws, "src/main/java", main.replace(/\./g, "/") + ".java"))) problems.push(`plugin.yml main is ${main} but src/main/java/${main.replace(/\./g, "/")}.java does not exist.`);
  if (/^(org\.bukkit|io\.papermc|net\.minecraft|com\.destroystokyo|net\.kyori)\./.test(main)) problems.push("The main class must be in your own package.");
  const apiMajor = rec.mcVersion.split(".").slice(0, 2).join(".");
  if (String(yml["api-version"] || "") !== apiMajor) {
    // Mechanical fix, not worth a model round-trip.
    yml["api-version"] = apiMajor;
    fs.writeFileSync(ymlPath, YAML.stringify(yml));
  }
  // getCommand("x") without a plugin.yml entry returns null at runtime -> NPE on enable.
  const declared = new Set(Object.keys((yml.commands && typeof yml.commands === "object") ? yml.commands : {}).map((s) => s.toLowerCase()));
  const java = listFiles(ws, "src/main/java").filter((f) => f.rel.endsWith(".java"));
  if (!java.length) problems.push("No Java source files were written.");
  for (const f of java) {
    const text = fs.readFileSync(f.abs, "utf8");
    for (const m of text.matchAll(/getCommand\(\s*"([^"]+)"\s*\)/g)) {
      if (!declared.has(m[1].toLowerCase())) problems.push(`${f.rel} calls getCommand("${m[1]}") but plugin.yml has no command "${m[1]}" (it would crash on enable).`);
    }
    if (/^\s*public\s+final\s+class\s+\w+\s+extends\s+JavaPlugin/m.test(text)) problems.push(`${f.rel}: the main class must not be final.`);
  }
  const total = listFiles(ws, "src").reduce((a, f) => a + f.size, 0);
  if (total > 1.5 * 1024 * 1024) problems.push("The source is too large (over 1.5 MB).");
  return { problems: [...new Set(problems)], yml };
}

async function compile(ws, rec, ctl) {
  const out = path.join(ws, "build/classes");
  rmrf(path.join(ws, "build")); fs.mkdirSync(out, { recursive: true });
  const cp = fs.readFileSync(path.join(CP_DIR, `${rec.mcVersion}.txt`), "utf8").trim();
  const sources = listFiles(ws, "src/main/java").filter((f) => f.rel.endsWith(".java")).map((f) => f.abs);
  const r = await run("javac", ["-J-Xmx768m", "--release", "21", "-encoding", "UTF-8", "-proc:none", "-Xmaxerrs", "40", "-Xlint:deprecation,removal", "-cp", cp, "-d", out, ...sources],
    { cwd: ws, env: childEnv(false), timeout: 180000, track: ctl });
  ctl.child = null;
  const output = (r.err + r.out).split(ws + "/").join("");
  if (r.code !== 0) return { ok: false, errors: output.slice(0, 12000) };
  // Resources (plugin.yml, config.yml, ...)
  copyDir(path.join(ws, "src/main/resources"), out);
  const jar = path.join(ws, "build/plugin.jar");
  const j = await run("jar", ["--create", "--file", jar, "-C", out, "."], { cwd: ws, env: childEnv(false), timeout: 60000 });
  if (j.code !== 0) return { ok: false, errors: j.err.slice(0, 4000) };
  const warnings = (output.match(/warning: \[(deprecation|removal)\][^\n]*/g) || []).slice(0, 10);
  return { ok: true, jar, classes: out, warnings };
}

// ------------------------------------------------------------ pipeline ----
async function runBuild(rec) {
  const ctl = { child: null, cancelled: false };
  running.set(rec.id, ctl);
  const started = Date.now();
  rec.startedAt = now();
  const ws = path.join(dirOf(rec.id), "ws");
  const killer = setTimeout(() => { ctl.cancelled = true; ctl.timeout = true; if (ctl.child) ctl.child.kill("SIGKILL"); }, BUILD_TIMEOUT_MS);
  try {
    rmrf(ws);
    if (rec.baseBuildId) {
      const baseWs = path.join(dirOf(rec.baseBuildId), "ws");
      if (!fs.existsSync(baseWs)) throw fail("bad_request", "The earlier build this change is based on is no longer available.");
      copyDir(baseWs, ws, (s) => !s.includes(`${path.sep}build`));
      setStage(rec, "planning", "Reading your existing plugin and planning the change");
    } else {
      copyDir(TEMPLATE, ws);
      setStage(rec, "planning", "Planning the plugin from your description");
    }

    let prompt = rec.baseBuildId ? P.changePrompt(rec) : P.initialPrompt(rec);
    let resume = null;
    let repairs = 0;
    let safetyRepairs = 0;
    let lastErr = "";
    for (;;) {
      rec.attempts += 1;
      await callClaude(rec, ctl, ws, prompt, { resume, model: resume ? REPAIR_MODEL : MODEL });
      resume = rec.sessionId;

      const summary = readSummary(ws);
      if (summary && summary.refused) {
        throw fail("refused", `We can't build this one. ${String(summary.reason || "It goes against our plugin safety rules.").slice(0, 300)}`);
      }
      sanitizeWorkspace(ws, rec);

      const secretHits = scanSecrets(listFiles(ws), SECRETS);
      if (secretHits.length) {
        rmrf(ws);
        log("error", "secret material found in generated source", { id: rec.id, files: secretHits });
        throw fail("safety", "The generated code was blocked by our safety checks.", "secret-scan");
      }

      setStage(rec, rec.attempts > 1 ? "repairing" : "compiling", rec.attempts > 1 ? `Checking the fix (attempt ${rec.attempts})` : "Checking the plugin files");
      const v = validate(ws, rec);
      let problem = null;
      if (v.problems.length) {
        problem = { kind: "compile", text: v.problems.map((p) => `- ${p}`).join("\n"), say: `${v.problems.length} setup problem${v.problems.length > 1 ? "s" : ""} found` };
      } else {
        setStage(rec, rec.attempts > 1 ? "repairing" : "compiling", `Compiling against Paper ${rec.mcVersion}${rec.attempts > 1 ? ` (attempt ${rec.attempts})` : ""}`);
        const c = await compile(ws, rec, ctl);
        if (ctl.cancelled) throw fail(ctl.timeout ? "timeout" : "cancelled", ctl.timeout ? "This build ran out of time." : "Build cancelled.");
        if (!c.ok) {
          const n = (c.errors.match(/ error(s)?$/m) || [])[0];
          const count = (c.errors.match(/^\d+ errors?$/m) || ["compile errors"])[0];
          problem = { kind: "compile", text: c.errors, say: `Compiler found ${count}` };
          void n;
        } else {
          event(rec, rec.status, "Compiled successfully");
          setStage(rec, "scanning", "Running the safety check");
          const findings = [...scanBytecode(c.classes), ...scanSource(listFiles(ws, "src/main/java").filter((f) => f.rel.endsWith(".java")))];
          const blocks = findings.filter((f) => f.severity === "block");
          if (blocks.length) {
            if (safetyRepairs >= 1 || repairs >= MAX_REPAIRS) {
              rec.safety = { verdict: "block", findings };
              throw fail("safety", `The plugin was blocked by our safety check: it ${blocks[0].message}. Try rewording the request without that part.`, blocks.map((b) => `${b.rule} ${b.where}: ${b.evidence}`).join("\n"));
            }
            safetyRepairs += 1;
            problem = { kind: "safety", text: blocks.map((b) => `- ${b.where}: ${b.message} (${b.evidence})`).join("\n"), say: `Safety check flagged ${blocks.length} thing${blocks.length > 1 ? "s" : ""}` };
          } else {
            const warns = findings.filter((f) => f.severity === "warn");
            rec.safety = { verdict: warns.length ? "warn" : "pass", findings };
            event(rec, "scanning", warns.length ? `Safety check passed with ${warns.length} note${warns.length > 1 ? "s" : ""}` : "Safety check passed: no network, no commands outside the game, own folder only");
            await finish(rec, ws, c, v.yml);
            return;
          }
        }
      }
      // ---- repair loop
      lastErr = problem.text;
      if (repairs >= MAX_REPAIRS) throw fail("compile", `We couldn't get this plugin to build after ${rec.attempts} tries. Try a simpler description, or split it into smaller plugins.`, lastErr);
      if (rec.costUsd >= BUILD_BUDGET_USD) throw fail("budget", "This build reached its spending cap before finishing. Try a smaller request.", lastErr);
      repairs += 1;
      rec.repairs = repairs;
      setStage(rec, "repairing", `${problem.say}. Fixing it automatically (fix ${repairs} of ${MAX_REPAIRS})`);
      event(rec, "repairing", "Error details", problem.text.slice(0, 3000));
      prompt = P.repairPrompt(problem.kind, problem.text.slice(0, 8000));
    }
  } catch (e) {
    rec.status = "failed";
    rec.errorCode = ctl.timeout ? "timeout" : (e.code || "internal");
    rec.error = ctl.timeout ? "This build ran out of time. Try a smaller request." : (e.code ? e.message : "Something went wrong on our side. Please try again.");
    rec.errorDetail = e.detail ? String(e.detail).slice(0, 8000) : (e.code ? undefined : String(e.stack || e).slice(0, 2000));
    if (!e.code) log("error", "build crashed", { id: rec.id, err: String(e.stack || e) });
