const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, "http://x");
  const parts = url.pathname.split("/").filter(Boolean);
  try {
    if (req.method === "GET" && url.pathname === "/health") {
      return send(res, 200, { ok: true, service: "nxeon-modbuilder", promptVersion: P.PROMPT_VERSION, model: MODEL, versions: VERSIONS, running: running.size, queued: queue.length, concurrency: CONCURRENCY, auth: process.env.ANTHROPIC_API_KEY ? "api_key" : process.env.CLAUDE_CODE_OAUTH_TOKEN ? "subscription" : "none" });
    }
    if (!authed(req)) return send(res, 401, { error: "unauthorized" });

    if (req.method === "POST" && url.pathname === "/builds") {
      const b = await readJson(req);
      const id = String(b.id || "");
      if (!/^[A-Za-z0-9_-]{6,64}$/.test(id)) return send(res, 400, { error: "id must be 6-64 chars [A-Za-z0-9_-]" });
      if (records.has(id)) return send(res, 202, publicView(records.get(id)));
      const mcVersion = String(b.mcVersion || VERSIONS[0]);
      if (!VERSIONS.includes(mcVersion)) return send(res, 400, { error: `mcVersion must be one of ${VERSIONS.join(", ")}` });
      const prompt = String(b.prompt || "").trim();
      if (prompt.length < 8 || prompt.length > 4000) return send(res, 400, { error: "prompt must be 8-4000 characters" });
      const changeRequest = b.changeRequest ? String(b.changeRequest).trim().slice(0, 2000) : "";
      const baseBuildId = b.baseBuildId ? String(b.baseBuildId) : null;
      if (baseBuildId) {
        const base = records.get(baseBuildId);
        if (!base || base.status !== "succeeded") return send(res, 400, { error: "baseBuildId must be a succeeded build" });
        if (!changeRequest) return send(res, 400, { error: "changeRequest required with baseBuildId" });
      }
      const pluginName = b.pluginName ? String(b.pluginName).replace(/[^A-Za-z0-9_]/g, "").slice(0, 40) : "";
      fs.mkdirSync(dirOf(id), { recursive: true });
      const rec = {
        id, status: "queued", prompt, changeRequest: changeRequest || null, baseBuildId, mcVersion, pluginName: pluginName || null,
        model: MODEL, promptVersion: P.PROMPT_VERSION, sessionId: crypto.randomUUID(),
        events: [{ at: now(), stage: "queued", message: "Waiting for a free builder" }],
        summary: null, commands: [], permissions: [], config: [], files: [], warnings: [], safety: null,
        error: null, errorCode: null, errorDetail: null, attempts: 0, repairs: 0, costUsd: 0, tokens: { input: 0, output: 0 }, aiCalls: [],
        durationMs: 0, jar: null, createdAt: now(), startedAt: null, finishedAt: null,
      };
      records.set(id, rec); save(rec);
      queue.push(id); pump();
      return send(res, 202, publicView(rec));
    }

    if (parts[0] === "builds" && parts[1]) {
      const rec = records.get(parts[1]);
      if (!rec) return send(res, 404, { error: "not found" });
      if (req.method === "GET" && parts.length === 2) return send(res, 200, publicView(rec));
      if (req.method === "POST" && parts[2] === "cancel") {
        if (rec.status === "queued") {
          const i = queue.indexOf(rec.id); if (i >= 0) queue.splice(i, 1);
          rec.status = "failed"; rec.errorCode = "cancelled"; rec.error = "Build cancelled."; rec.finishedAt = now(); save(rec);
        } else {
          const ctl = running.get(rec.id);
          if (ctl) { ctl.cancelled = true; if (ctl.child) ctl.child.kill("SIGKILL"); }
        }
        return send(res, 200, { ok: true });
      }
      if (req.method === "GET" && parts[2] === "artifact") {
        const f = path.join(dirOf(rec.id), "artifact.jar");
        if (rec.status !== "succeeded" || !fs.existsSync(f)) return send(res, 404, { error: "no artifact" });
        res.writeHead(200, { "Content-Type": "application/java-archive", "Content-Length": fs.statSync(f).size, "Content-Disposition": `attachment; filename="${rec.jar.name}"`, "X-Sha256": rec.jar.sha256 });
        return fs.createReadStream(f).pipe(res);
      }
      if (req.method === "GET" && parts[2] === "source") {
        const ws = path.join(dirOf(rec.id), "ws");
        const rel = String(url.searchParams.get("path") || "");
        if (!rel) return send(res, 200, { files: srcList(ws) });
        const abs = path.resolve(ws, rel);
        if (!abs.startsWith(ws + path.sep) || rel.startsWith("build/") || !fs.existsSync(abs) || !fs.statSync(abs).isFile() || fs.lstatSync(abs).isSymbolicLink()) return send(res, 404, { error: "no such file" });
        if (fs.statSync(abs).size > 512 * 1024) return send(res, 413, { error: "file too large" });
        res.writeHead(200, { "Content-Type": "text/plain; charset=utf-8", "Cache-Control": "no-store" });
        return res.end(fs.readFileSync(abs));
      }
      if (req.method === "GET" && parts[2] === "source.zip") {
        const ws = path.join(dirOf(rec.id), "ws");
        if (!fs.existsSync(ws)) return send(res, 404, { error: "no source" });
        const tmp = path.join(dirOf(rec.id), "source.zip");
        rmrf(tmp);
        const files = srcList(ws).map((f) => f.path);
        execFileSync("jar", ["--create", "--no-manifest", "--file", tmp, ...files], { cwd: ws, env: childEnv(false), timeout: 30000 });
        res.writeHead(200, { "Content-Type": "application/zip", "Content-Disposition": `attachment; filename="${(rec.pluginName || "plugin")}-source.zip"` });
        return fs.createReadStream(tmp).pipe(res);
      }
    }
    return send(res, 404, { error: "not found" });
  } catch (e) {
    log("error", "request failed", { path: url.pathname, err: String(e) });
    return send(res, 500, { error: "internal error" });
  }
});

if (!API_KEY) log("warn", "MODBUILDER_API_KEY is not set: every authenticated route will 401");
server.listen(PORT, "0.0.0.0", () => log("info", "modbuilder listening", { port: PORT, model: MODEL, versions: VERSIONS, concurrency: CONCURRENCY }));

