// ── the viewer's servers + what is on them ──────────────────────────────────

export type LabsServer = { id: string; name: string; family: string; variant: string | null; status: string };
/** Per mod id: which of my servers it's on and in what state. */
export type InstallState = Record<string, { serverId: string; status: string }[]>;

/** The signed-in customer's game servers that take mods (familyFor != null). */
export async function myModServers(userId: string): Promise<LabsServer[]> {
  const rows = await db.server.findMany({
    where: { userId, status: { notIn: ["DELETING"] } },
    include: { osTemplate: true, gamePlan: true },
    orderBy: { createdAt: "asc" },
  });
  const out: LabsServer[] = [];
  for (const s of rows) {
    const family = familyFor(s);
    if (family) out.push({ id: s.id, name: s.label || s.hostname, family, variant: s.gameVariant ?? null, status: s.status });
  }
  return out;
}

/** Install rows (any live state) for the given mods on the given servers. */
export async function installStateFor(serverIds: string[], modIds: string[]): Promise<InstallState> {
  if (!serverIds.length || !modIds.length) return {};
  const rows = await db.serverMod.findMany({
    where: { serverId: { in: serverIds }, modId: { in: modIds }, status: { not: "REMOVED" } },
    select: { serverId: true, modId: true, status: true },
  });
  const out: InstallState = {};
  for (const r of rows) (out[r.modId] ??= []).push({ serverId: r.serverId, status: r.status });
  return out;
}

/** Everything installed (or installing / failed) on my servers — the Installed view. */
export async function myInstalledMods(serverIds: string[]) {
  if (!serverIds.length) return [];
  return db.serverMod.findMany({
    where: { serverId: { in: serverIds }, status: { not: "REMOVED" } },
    include: { mod: { select: { id: true, name: true, slug: true, gameFamily: true, iconUrl: true, category: true, description: true, source: true, active: true, upstreamOk: true } } },
    orderBy: [{ updatedAt: "desc" }],
  });

