// Private-preview gate for features that are live in code but only visible to
// an allowlist of accounts (the owner, while a feature is being tested).
//
// Allowlist: Setting `preview_access_emails` (comma-separated emails). When
// the setting has never been written, the code default below applies. Fails
// closed: any DB error means "not a preview user".
//
// Kept deliberately tiny and identical in spirit to the copy on the dedicated
// preview branch, so the two merge trivially.
import { getSetting } from "./settings";

export type PreviewFeature = "dedicated" | "modbuilder";

export const PREVIEW_ACCESS_SETTING = "preview_access_emails";
export const PREVIEW_ACCESS_DEFAULT = "nicholas.sj.albanese@gmail.com";

export function parsePreviewEmails(raw: string | null | undefined): string[] {
  return String(raw ?? "")
    .split(",")
    .map((s) => s.trim().toLowerCase())
    .filter(Boolean);
}

/** Pure check, unit-testable. */
export function emailAllowed(email: string | null | undefined, allow: string[]): boolean {
  const e = String(email ?? "").trim().toLowerCase();
  return !!e && allow.includes(e);
}

// `feature` is accepted so per-feature allowlists can be added later without
// touching call sites; today every preview feature shares one list.
export async function isPreviewUser(user: { email?: string | null } | null | undefined, feature: PreviewFeature): Promise<boolean> {
  void feature;
  if (!user?.email) return false;
  try {
    const raw = await getSetting(PREVIEW_ACCESS_SETTING, PREVIEW_ACCESS_DEFAULT);
    return emailAllowed(user.email, parsePreviewEmails(raw || PREVIEW_ACCESS_DEFAULT));
  } catch {
    return false;
  }
}

