// Shared (client-safe) types and constants for the AI Mod Builder.

export const MB_VERSIONS = ["1.21.11", "1.21.8", "1.21.4", "1.21.1"] as const;
export type McVersion = (typeof MB_VERSIONS)[number];
export const MB_DEFAULT_VERSION: McVersion = "1.21.11";

export type ModBuildStatus = "queued" | "planning" | "coding" | "compiling" | "repairing" | "scanning" | "succeeded" | "failed";
export const MB_TERMINAL: ModBuildStatus[] = ["succeeded", "failed"];
export const isTerminal = (s: string) => s === "succeeded" || s === "failed";

export type MbEvent = { at: string; stage: string; message: string; detail?: string };
export type MbCommand = { usage: string; description: string; permission: string; whoCanUse: string };
export type MbPermission = { node: string; description: string; default: string };
export type MbConfig = { key: string; description: string; default: string };
export type MbFinding = { severity: "block" | "warn"; rule: string; where: string; message: string; evidence: string };

/** What the portal keeps in ModBuild.result (a trimmed mirror of the service record). */
export type ModBuildResult = {
  summary: { tagline: string; text: string; howToUse: string[]; limitations: string[]; changes: string } | null;
  commands: MbCommand[];
  permissions: MbPermission[];
  config: MbConfig[];
  warnings: string[];
  files: { path: string; size: number }[];
  safety: { verdict: "pass" | "warn" | "block"; findings: MbFinding[] } | null;
  events: MbEvent[];
  repairs: number;
  queuePosition: number;
  errorDetail?: string | null;
};

/** The view the client polls. */
export type ModBuildView = {
  id: string;
  status: ModBuildStatus;
  prompt: string;
  changeRequest: string | null;
  baseBuildId: string | null;
  rootBuildId: string | null;
  mcVersion: string;
  pluginName: string | null;
  version: string | null;
  error: string | null;
  errorCode: string | null;
  attempts: number;
  durationMs: number | null;
  jarName: string | null;
  jarSize: number | null;
  createdAt: string;
  finishedAt: string | null;
  result: ModBuildResult | null;
  lastInstall: { serverId: string; serverName: string; at: string; replaced: string[]; restarted: boolean } | null;
};

/** Customer-facing stage list for the progress timeline. */
export const MB_STAGES: { key: string; label: string; sub: string }[] = [
  { key: "planning", label: "Planning", sub: "Working out what to build" },
  { key: "coding", label: "Writing code", sub: "The AI writes your plugin" },
  { key: "compiling", label: "Compiling", sub: "Turning it into a real plugin file" },
  { key: "repairing", label: "Fixing", sub: "Only if something needs a fix" },
  { key: "scanning", label: "Safety check", sub: "No internet, no system access" },
  { key: "succeeded", label: "Ready", sub: "Download or install it" },
];

export const MB_IDEAS: { label: string; icon: string; prompt: string }[] = [
  { label: "Economy shop", icon: "wallet", prompt: "A simple economy: players earn coins for killing mobs, can check /balance and /pay each other, and /shop opens a chest menu where they spend coins on diamonds, golden apples and ender pearls. Prices are set in the config." },
  { label: "Join rewards", icon: "sparkles", prompt: "Daily join rewards: the first time a player joins each day they get a reward that grows with their login streak (day 1: 5 bread, day 3: iron, day 7: a diamond). Show a welcome title and their current streak. Streaks are saved." },
  { label: "Custom commands", icon: "terminal", prompt: "Handy player commands: /spawn teleports to the world spawn, /sethome and /home save and return to one home per player, and /discord, /rules and /website print messages I can edit in the config." },
  { label: "Anti-grief zones", icon: "shieldcheck", prompt: "Protected zones: operators mark two corners with /zone pos1 and /zone pos2 and save them with /zone create <name>. Inside a zone, players without permission can't break or place blocks, open chests or explode TNT. Zones survive restarts." },
  { label: "Scoreboard", icon: "chart", prompt: "A sidebar scoreboard showing the server name, the player's kills, deaths, play time and how many players are online. It updates every few seconds and the title and colours are configurable." },
  { label: "Mini-game", icon: "gamepad", prompt: "A spleef mini-game: operators set the arena and lobby with commands, players /spleef join, a countdown starts when 2 or more are waiting, everyone gets a shovel, and the last player standing wins and is announced to the server." },
  { label: "Chat tools", icon: "chatcode", prompt: "Chat improvements: a configurable chat format with ranks by permission, a word filter that replaces bad words with ***, and /msg and /reply for private messages." },
  { label: "Custom mob drops", icon: "cube", prompt: "Custom mob drops: zombies have a 5% chance to drop an emerald, skeletons drop extra arrows and creepers sometimes drop a TNT block. All chances and items are set in the config." },
];
EOF
