import { isSafeAbs } from "./paths";

export type GuestStat = { type: "file" | "dir"; size: number };

export interface GuestFs {
  readonly kind: "ssh" | "local";
  stat(p: string): Promise<GuestStat | null>;
  readFile(p: string, maxBytes?: number): Promise<Buffer | null>;
  /** Creates parent directories. */
  writeFile(p: string, data: Buffer): Promise<void>;
  mkdirp(p: string): Promise<void>;
  /** Move, overwriting a file at `to`. Creates the destination's parent. */
  rename(from: string, to: string): Promise<void>;
  /** File or directory (recursive). Missing is not an error. */
  remove(p: string): Promise<void>;
  /** Entry names; [] when missing. */
  list(dir: string): Promise<string[]>;
  /** Best-effort: give `paths` the owner/group of `ref` (real guests only). */
  chownLike(ref: string, paths: string[]): Promise<void>;
  /** Copy a file (used for backups). */
  copy(from: string, to: string): Promise<void>;
}

function assertAbs(p: string) {
  if (!isSafeAbs(p)) throw new Error(`unsafe guest path: ${p}`);
}

export class LocalGuestFs implements GuestFs {
  }
}

/** Where SANDBOX keeps each server's fake guest tree. */
export function sandboxGuestRoot(serverId: string): string {
  const base = process.env.NXEON_SANDBOX_GUEST_DIR || "/tmp/nxeon-sandbox-guests";
  return path.join(base, serverId.replace(/[^A-Za-z0-9_-]/g, ""));
}

/** Minimal per-family skeletons so detect() has something real to find in SANDBOX. */
export async function seedSandboxGuest(fs: GuestFs, family: string, variant: string | null): Promise<void> {
  const put = async (p: string, s: string) => {
    if (!(await fs.stat(p))) await fs.writeFile(p, Buffer.from(s));
  };
  switch (family) {
    case "minecraft":
      await put("/opt/mc/server.properties", "level-name=world\nmotd=Nxeon sandbox\n");
      await put("/opt/mc/logs/latest.log", "[00:00:00] [Server thread/INFO]: Starting minecraft server version 1.21.1\n");
      await fs.mkdirp(variant && ["fabric", "forge", "neoforge", "quilt"].includes(variant) ? "/opt/mc/mods" : "/opt/mc/plugins");
      await fs.mkdirp("/opt/mc/world/datapacks");
      break;
    case "valheim":
      await fs.mkdirp("/opt/valheim/config/bepinex/plugins");
      break;
    case "rust":
      await fs.mkdirp("/opt/rust/oxide/plugins");
      break;
    case "cs2":
      await fs.mkdirp("/opt/cs2/game/csgo/addons/metamod");
      await fs.mkdirp("/opt/cs2/game/csgo/addons/counterstrikesharp/plugins");
      break;
    case "factorio":
      await put("/opt/factorio/config/server-settings.json", JSON.stringify({ name: "Nxeon sandbox", username: "", token: "" }, null, 2));
      await put("/opt/factorio/factorio-current.log", "   0.000 2026-10-01 00:00:00; Factorio 2.0.66 (build 83000, linux64, headless)\n");
      await put("/opt/factorio/mods/mod-list.json", JSON.stringify({ mods: [{ name: "base", enabled: true }] }, null, 2));
      break;
    default:
      break;
  }
}
