// Install a finished Mod Builder jar into one of the user's Minecraft servers.
//
// Reuses the mods engine's guest transport (worker/mods-guest-ssh.ts SshGuestFs,
// the same SSH+SFTP path the NxLabs installer uses, management key first) and
// its backup convention (/root/.nxeon-mods/backups/<stamp>-<label>/<abs path>).
// In SANDBOX the same steps run against LocalGuestFs (lib/mods/guest-fs.ts).
//
// Steps: check ownership + Paper/Purpur -> back up and remove any earlier jar of
// the same plugin -> write <Name>-<ver>.jar via a .part file + rename -> chown
// like plugins/ -> optional restart through the normal gamePower job.
import type { ModBuild } from "@prisma/client";
import { db } from "../db";
import { SANDBOX } from "../sandbox";
import { familyFor } from "../game-config";
import { LocalGuestFs, sandboxGuestRoot, seedSandboxGuest, type GuestFs } from "../mods/guest-fs";
import { safeFileName } from "../mods/paths";
import { SshGuestFs } from "../../worker/mods-guest-ssh";
import { readJar } from "./store";

const MC_BASE = "/opt/mc";
const PLUGINS = `${MC_BASE}/plugins`;
const BACKUPS = "/root/.nxeon-mods/backups";
/** Generated plugins target the Paper API (Adventure etc.), so Spigot/Bukkit can't load them, and they aren't Folia-safe. */
export const MB_INSTALL_VARIANTS = ["paper", "purpur"];

export type MbServer = { id: string; name: string; variant: string | null; status: string; compatible: boolean; reason?: string };

/** The user's Minecraft servers, each marked whether a builder plugin can go on it. */
export async function modBuilderServers(userId: string): Promise<MbServer[]> {
  const rows = await db.server.findMany({
    where: { userId, status: { notIn: ["DELETING"] } },
    include: { osTemplate: true, gamePlan: true },
    orderBy: { createdAt: "asc" },
  });
  const out: MbServer[] = [];
  for (const s of rows) {
    if (familyFor(s) !== "minecraft") continue;
    const variant = (s.gameVariant || "vanilla").toLowerCase();
    const okVariant = MB_INSTALL_VARIANTS.includes(variant);
    const okStatus = s.status === "RUNNING" || s.status === "STOPPED";
    out.push({
      id: s.id,
      name: s.label || s.hostname,
      variant,
      status: s.status,
      compatible: okVariant && okStatus,
      reason: !okVariant ? `Runs ${variant[0].toUpperCase() + variant.slice(1)}; plugins need Paper or Purpur` : !okStatus ? `Server is ${s.status.toLowerCase()}` : undefined,
    });
  }
  return out;
}

function stamp(d = new Date()) {
  return d.toISOString().replace(/[-:]/g, "").replace(/\..+$/, "").replace("T", "-");
}

export type InstallResult = { ok: true; path: string; replaced: string[]; backupDir: string | null; serverName: string } | { ok: false; error: string };

export async function installBuildToServer(build: ModBuild, userId: string, serverId: string): Promise<InstallResult> {
  if (build.userId !== userId) return { ok: false, error: "Not found." };
  if (build.status !== "succeeded" || !build.jarName || !build.pluginName) return { ok: false, error: "This build has no plugin file to install." };
  const server = await db.server.findUnique({ where: { id: serverId }, include: { osTemplate: true, gamePlan: true, dedicatedIp: true, node: true } });
  if (!server || server.userId !== userId) return { ok: false, error: "Server not found." };
  const servers = await modBuilderServers(userId);
  const facts = servers.find((s) => s.id === serverId);
  if (!facts) return { ok: false, error: "That server isn't a Minecraft server." };
  if (!facts.compatible) return { ok: false, error: facts.reason || "That server can't take this plugin." };

  const fileName = safeFileName(build.jarName, [".jar"]);
  if (!fileName) return { ok: false, error: "The plugin file name isn't safe to write." };
  const bytes = await readJar(build);

  let fs: GuestFs;
  let ssh: SshGuestFs | null = null;
  try {
    if (SANDBOX) {
      const local = new LocalGuestFs(sandboxGuestRoot(server.id));
      await seedSandboxGuest(local, "minecraft", server.gameVariant ?? null);
      fs = local;
    } else {
      ssh = await SshGuestFs.open(server);
      fs = ssh;
    }
    if (!(await fs.stat(MC_BASE))) return { ok: false, error: "Couldn't find the Minecraft folder on this server. Is it fully set up?" };
    await fs.mkdirp(PLUGINS);

    // Earlier copies of this plugin: same jar name, or "<PluginName>-*.jar" /
    // "<PluginName>.jar" (case-insensitive) that a previous builder install left.
    const name = build.pluginName.toLowerCase();
    const existing = (await fs.list(PLUGINS)).filter((f) => {
      const l = f.toLowerCase();
      return l === fileName.toLowerCase() || l === `${name}.jar` || (l.startsWith(`${name}-`) && l.endsWith(".jar"));
    });
    let backupDir: string | null = null;
    if (existing.length) {
      backupDir = `${BACKUPS}/${stamp()}-modbuilder-${safeFileName(build.pluginName, [""]) || "plugin"}`;
      for (const f of existing) await fs.copy(`${PLUGINS}/${f}`, `${backupDir}${PLUGINS}/${f}`);
    }
    const dest = `${PLUGINS}/${fileName}`;
    const part = `${PLUGINS}/.${fileName}.part`;
    await fs.writeFile(part, bytes);
    for (const f of existing) if (f !== fileName) await fs.remove(`${PLUGINS}/${f}`);
    await fs.rename(part, dest);
    await fs.chownLike(PLUGINS, [dest]);
    return { ok: true, path: dest, replaced: existing, backupDir, serverName: facts.name };
  } catch (e) {
    console.error("[modbuilder] install failed", build.id, serverId, (e as Error).message);
    return { ok: false, error: "We couldn't reach the server to copy the plugin. Check it's online and try again." };
  } finally {
    ssh?.close();
  }
}

