  font-size: 11px; font-weight: 800; letter-spacing: .02em; white-space: nowrap; border: 1px solid transparent;
}
.mb-root .mb-pill .dot { width: 6px; height: 6px; border-radius: 99px; background: currentColor; }
.mb-root .mb-pill.run { color: #8fd8ff; background: rgba(20,197,228,.12); border-color: rgba(20,197,228,.3); }
.mb-root .mb-pill.run .dot { animation: mb-pulse 1.2s ease-in-out infinite; }
.mb-root .mb-pill.ok { color: #4fe3b0; background: rgba(17,200,142,.12); border-color: rgba(17,200,142,.32); }
.mb-root .mb-pill.bad { color: #ff8fa6; background: rgba(255,90,120,.1); border-color: rgba(255,90,120,.3); }
.mb-root .mb-pill.warn { color: #ffcf7a; background: rgba(255,180,60,.1); border-color: rgba(255,180,60,.3); }
html[data-theme="light"] .mb-root .mb-pill.run { color: #0a6f8c; }
html[data-theme="light"] .mb-root .mb-pill.ok { color: #08795a; }
html[data-theme="light"] .mb-root .mb-pill.bad { color: #b4203f; }
html[data-theme="light"] .mb-root .mb-pill.warn { color: #8a5a00; }

@keyframes mb-pulse { 0%, 100% { opacity: 1; transform: scale(1); } 50% { opacity: .35; transform: scale(.75); } }
@keyframes mb-spin { to { transform: rotate(360deg); } }
@keyframes mb-sheen { from { background-position: -200% 0; } to { background-position: 200% 0; } }
@keyframes mb-rise { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: none; } }

/* ── build list ───────────────────────────────────────────────────────── */
.mb-root .mb-row { display: grid; grid-template-columns: 40px minmax(0,1fr) auto; gap: 12px; align-items: center; padding: 12px 14px; border-radius: 14px; transition: background .15s; }
.mb-root .mb-row:hover { background: color-mix(in srgb, var(--color-violet) 9%, transparent); }
.mb-root .mb-row + .mb-row { border-top: 1px solid var(--color-rim-soft); }
.mb-root .mb-tile {
  width: 40px; height: 40px; border-radius: 12px; display: grid; place-items: center;
  background: linear-gradient(140deg, rgba(20,197,228,.18), rgba(140,58,233,.24)); border: 1px solid rgba(150,175,255,.2);
}

/* ── progress timeline ────────────────────────────────────────────────── */
.mb-root .mb-steps { display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 0; position: relative; }
.mb-root .mb-step { position: relative; display: flex; flex-direction: column; align-items: center; text-align: center; gap: 8px; padding: 0 4px; }
.mb-root .mb-step::before {
  content: ""; position: absolute; top: 17px; left: calc(-50% + 22px); right: calc(50% + 22px); height: 2px; border-radius: 2px;
  background: var(--color-rim-hi);
}
.mb-root .mb-step:first-child::before { display: none; }
.mb-root .mb-step.done::before, .mb-root .mb-step.now::before { background: linear-gradient(90deg, #14c5e4, #8c3ae9); }
.mb-root .mb-node {
  width: 36px; height: 36px; border-radius: 999px; display: grid; place-items: center; position: relative; z-index: 1;
  background: var(--color-well); border: 2px solid var(--color-rim-hi); color: var(--color-tx-faint);
}
.mb-root .mb-step.done .mb-node { background: linear-gradient(140deg, #14c5e4, #8c3ae9); border-color: transparent; color: #fff; }
.mb-root .mb-step.now .mb-node { border-color: #8c7bff; color: #fff; background: rgba(140, 58, 233, .22); box-shadow: 0 0 0 6px rgba(140, 58, 233, .14), 0 0 26px rgba(120, 100, 255, .55); }
.mb-root .mb-step.now .mb-node::after {
  content: ""; position: absolute; inset: -6px; border-radius: 999px; border: 2px solid transparent;
  border-top-color: #5ce1ff; border-right-color: #b98cff; animation: mb-spin 1.1s linear infinite;
}
.mb-root .mb-step.skip .mb-node { opacity: .45; border-style: dashed; }
.mb-root .mb-step.fail .mb-node { background: rgba(255,90,120,.16); border-color: rgba(255,90,120,.55); color: #ff8fa6; }
.mb-root .mb-step-l { font-size: 12.5px; font-weight: 800; color: var(--color-tx); }
.mb-root .mb-step.pending .mb-step-l, .mb-root .mb-step.skip .mb-step-l { color: var(--color-tx-faint); }
.mb-root .mb-step-s { font-size: 11px; line-height: 1.35; color: var(--color-tx-faint); max-width: 16ch; }
@media (max-width: 720px) {
  .mb-root .mb-steps { grid-template-columns: 1fr; gap: 14px; }
  .mb-root .mb-step { flex-direction: row; text-align: left; gap: 12px; }
  .mb-root .mb-step::before { top: auto; bottom: calc(100% - 4px); left: 17px; right: auto; width: 2px; height: 18px; }
  .mb-root .mb-step-s { max-width: none; }
}
.mb-root .mb-bar { height: 4px; border-radius: 99px; overflow: hidden; background: var(--color-rim-soft); }
.mb-root .mb-bar > i {
  display: block; height: 100%; border-radius: 99px; transition: width .8s cubic-bezier(.2,.8,.2,1);
  background: linear-gradient(90deg, #14c5e4, #2f7eef, #8c3ae9, #14c5e4); background-size: 200% 100%; animation: mb-sheen 2.4s linear infinite;
}
.mb-root .mb-log { font-size: 12.5px; }
.mb-root .mb-log li { display: grid; grid-template-columns: 54px 16px minmax(0,1fr); gap: 8px; align-items: start; padding: 5px 0; animation: mb-rise .25s ease-out; }
.mb-root .mb-log time { font-variant-numeric: tabular-nums; color: var(--color-tx-faint); font-size: 11.5px; padding-top: 1px; }

/* ── result ───────────────────────────────────────────────────────────── */
.mb-root .mb-success {
  position: relative; overflow: hidden; border-radius: 20px; border: 1px solid rgba(17, 200, 142, .28);
  background:
    radial-gradient(60% 120% at 0% 0%, rgba(17, 200, 142, .16), transparent 60%),
    radial-gradient(50% 120% at 100% 0%, rgba(140, 58, 233, .2), transparent 60%),
    #030816;
}
.mb-root .mb-failure {
  position: relative; overflow: hidden; border-radius: 20px; border: 1px solid rgba(255, 120, 140, .25);
  background: radial-gradient(60% 120% at 0% 0%, rgba(255, 90, 120, .13), transparent 60%), #030816;
}
.mb-root .mb-kbd {
  font-family: var(--font-mono, ui-monospace, SFMono-Regular, Menlo, monospace); font-size: 12.5px; font-weight: 700;
  padding: 3px 8px; border-radius: 8px; color: var(--color-tx);
  background: color-mix(in srgb, var(--color-violet) 14%, var(--color-well)); border: 1px solid color-mix(in srgb, var(--color-violet) 30%, transparent);
  overflow-wrap: anywhere;
}
.mb-root .mb-who { font-size: 10.5px; font-weight: 800; letter-spacing: .04em; padding: 2px 8px; border-radius: 99px; white-space: nowrap; color: var(--color-tx-mute); background: var(--color-well); border: 1px solid var(--color-rim-hi); }
.mb-root .mb-who.all { color: #4fe3b0; border-color: rgba(17,200,142,.3); background: rgba(17,200,142,.08); }
html[data-theme="light"] .mb-root .mb-who.all { color: #08795a; }
.mb-root .mb-check { display: flex; align-items: center; gap: 9px; font-size: 12.5px; font-weight: 600; color: var(--color-tx-body); }

/* ── source viewer ────────────────────────────────────────────────────── */
.mb-root .mb-src { display: grid; grid-template-columns: 250px minmax(0,1fr); min-height: 420px; border-radius: 16px; overflow: hidden; border: 1px solid rgba(140,180,255,.14); background: #040b1f; }
@media (max-width: 860px) { .mb-root .mb-src { grid-template-columns: 1fr; } }
.mb-root .mb-tree { border-right: 1px solid rgba(140,180,255,.1); padding: 10px 6px; overflow: auto; max-height: 560px; background: #030817; }
@media (max-width: 860px) { .mb-root .mb-tree { border-right: 0; border-bottom: 1px solid rgba(140,180,255,.1); max-height: 210px; } }
.mb-root .mb-tree button { display: flex; width: 100%; align-items: center; gap: 7px; padding: 5px 8px; border-radius: 8px; font-size: 12.5px; color: #b3c3ea; text-align: left; }
.mb-root .mb-tree button:hover { background: rgba(255,255,255,.05); color: #fff; }
.mb-root .mb-tree button.on { background: rgba(140, 58, 233, .22); color: #fff; }
.mb-root .mb-tree .dir { padding: 7px 8px 3px; font-size: 10.5px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; color: #6c80b5; }
.mb-root .mb-code { overflow: auto; max-height: 560px; font-family: var(--font-mono, ui-monospace, SFMono-Regular, Menlo, monospace); font-size: 12.5px; line-height: 1.6; color: #d6e2ff; }
.mb-root .mb-code table { border-collapse: collapse; width: 100%; }
.mb-root .mb-code td.n { user-select: none; text-align: right; padding: 0 12px 0 14px; color: #4b5d8c; width: 1%; white-space: nowrap; vertical-align: top; }
.mb-root .mb-code td.c { white-space: pre; padding-right: 18px; }
.mb-root .mb-code .k { color: #c792ff; } .mb-root .mb-code .s { color: #7ee0b5; } .mb-root .mb-code .m { color: #5f73a6; font-style: italic; }
.mb-root .mb-code .t { color: #6fd3ff; } .mb-root .mb-code .a { color: #ffcf7a; }

/* ── modal ────────────────────────────────────────────────────────────── */
.mb-modal-back { position: fixed; inset: 0; z-index: 80; display: grid; place-items: center; padding: 16px; background: rgba(1, 4, 14, .66); backdrop-filter: blur(6px); animation: mb-rise .15s ease-out; }
.mb-modal-back .mb-modal { width: 100%; max-width: 560px; max-height: calc(100dvh - 32px); overflow: auto; }
.mb-root .mb-opt { display: flex; align-items: center; gap: 12px; padding: 12px 14px; border-radius: 14px; border: 1px solid var(--color-rim-hi); background: var(--color-well); cursor: pointer; transition: border-color .15s, background .15s; }
.mb-root .mb-opt:hover { border-color: color-mix(in srgb, var(--color-violet) 55%, transparent); }
.mb-root .mb-opt.on { border-color: #8c7bff; background: color-mix(in srgb, var(--color-violet) 14%, var(--color-well)); }
.mb-root .mb-opt.off { opacity: .55; cursor: not-allowed; }

@media (prefers-reduced-motion: reduce) {
  .mb-root *, .mb-modal-back { animation: none !important; transition: none !important; }
}

