import type { Metadata } from "next";
import { db } from "@/lib/db";
import { requireModBuilderUser } from "@/lib/modbuilder/access";
import { svcHealth } from "@/lib/modbuilder/client";
import { toView } from "@/lib/modbuilder/store";
import { modBuilderServers } from "@/lib/modbuilder/install";
import { ModBuilderHome } from "@/components/nx/modbuilder/ModBuilderHome";
import "./mb.css";

export const dynamic = "force-dynamic";
export const metadata: Metadata = { title: "AI Mod Builder", robots: { index: false, follow: false } };

/**
