import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { db } from "@/lib/db";
import { requireModBuilderUser } from "@/lib/modbuilder/access";
import { syncBuild, toView } from "@/lib/modbuilder/store";
import { modBuilderServers } from "@/lib/modbuilder/install";
import { BuildView } from "@/components/nx/modbuilder/BuildView";
import "../mb.css";

export const dynamic = "force-dynamic";
export const metadata: Metadata = { title: "Plugin build · AI Mod Builder", robots: { index: false, follow: false } };

export default async function ModBuildPage({ params }: { params: Promise<{ id: string }> }) {
  const user = await requireModBuilderUser();
  const { id } = await params;
  let row = await db.modBuild.findUnique({ where: { id } });
  if (!row || row.userId !== user.id) notFound();
  try { row = await syncBuild(row); } catch { /* the client keeps polling */ }
  const root = row.rootBuildId ?? row.id;
  const [history, servers] = await Promise.all([
    db.modBuild.findMany({
      where: { userId: user.id, OR: [{ rootBuildId: root }, { id: root }] },
      orderBy: { createdAt: "asc" },
      select: { id: true, status: true, version: true, changeRequest: true, createdAt: true },
    }),
    modBuilderServers(user.id),
  ]);
  return (
    <BuildView
      initial={toView(row)}
      servers={servers}
      history={history.map((h) => ({ id: h.id, status: h.status, version: h.version, changeRequest: h.changeRequest, createdAt: h.createdAt.toISOString() }))}
    />
  );
}
EOF
