"use client";

import { Icon } from "@/components/nx/Icon";
import type { ModBuildStatus } from "@/lib/modbuilder/types";

export const STATUS_LABEL: Record<string, string> = {
  queued: "In line",
  planning: "Planning",
  coding: "Writing code",
  compiling: "Compiling",
  repairing: "Fixing",
  scanning: "Safety check",
  succeeded: "Ready",
  failed: "Didn't work",
};

export function StatusPill({ status }: { status: ModBuildStatus | string }) {
  const cls = status === "succeeded" ? "ok" : status === "failed" ? "bad" : "run";
  return (
    <span className={`mb-pill ${cls}`}>
      <span className="dot" />
      {STATUS_LABEL[status] ?? status}
    </span>
  );
}

export function PreviewBadge() {
  return (
    <span className="mb-preview" title="Private preview: only you can see this">
      <Icon name="sparkles" size={9} tone="inherit" />
      Preview
    </span>
  );
}

export function ago(iso: string): string {
  const s = Math.max(0, (Date.now() - new Date(iso).getTime()) / 1000);
  if (s < 45) return "just now";
  if (s < 3600) return `${Math.round(s / 60)} min ago`;
  if (s < 86400) return `${Math.round(s / 3600)} h ago`;
  const d = Math.round(s / 86400);
  return d === 1 ? "yesterday" : `${d} days ago`;
}

export function dur(ms: number | null | undefined): string {
  if (!ms || ms < 0) return "0s";
  const s = Math.round(ms / 1000);
  return s < 60 ? `${s}s` : `${Math.floor(s / 60)}m ${String(s % 60).padStart(2, "0")}s`;
}

export function bytes(n: number | null | undefined): string {
  if (!n) return "0 B";
  return n < 1024 ? `${n} B` : n < 1024 * 1024 ? `${(n / 1024).toFixed(1)} KB` : `${(n / 1048576).toFixed(1)} MB`;
}

export function Spinner({ size = 14 }: { size?: number }) {
  return (
    <span
      aria-hidden
      style={{ width: size, height: size, borderWidth: 2, animation: "mb-spin .8s linear infinite" }}
      className="inline-block flex-none rounded-full border-current border-r-transparent"
    />
  );
}

/** First sentence-ish of a prompt, for list rows. */
export function promptTitle(p: string, n = 90): string {
  const one = p.replace(/\s+/g, " ").trim();
  return one.length > n ? one.slice(0, n - 1).trimEnd() + "…" : one;
}

