"use client";

import Link from "next/link";
import { useEffect, useRef, useState } from "react";
import { useRouter } from "next/navigation";
import { Icon } from "@/components/nx/Icon";
import { MB_DEFAULT_VERSION, MB_IDEAS, MB_VERSIONS, isTerminal, type ModBuildView } from "@/lib/modbuilder/types";
import { PreviewBadge, Spinner, StatusPill, ago, promptTitle } from "./bits";

const MAX = 4000;

export function ModBuilderHome({ firstName, builds, online, serverCount }: { firstName: string; builds: ModBuildView[]; online: boolean; serverCount: number }) {
  const router = useRouter();
  const [prompt, setPrompt] = useState("");
  const [version, setVersion] = useState<string>(MB_DEFAULT_VERSION);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const ta = useRef<HTMLTextAreaElement>(null);
  const running = builds.filter((b) => !isTerminal(b.status));

  // Keep the list's statuses fresh while something is building.
  useEffect(() => {
    if (!running.length) return;
    const t = setInterval(() => router.refresh(), 5000);
    return () => clearInterval(t);
  }, [running.length, router]);

  async function submit(text = prompt) {
    const p = text.trim();
    if (p.length < 12) { setErr("Tell us a bit more about what the plugin should do."); ta.current?.focus(); return; }
    setBusy(true); setErr(null);
    try {
      const r = await fetch("/api/mod-builder/builds", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ prompt: p, mcVersion: version }) });
      const j = await r.json().catch(() => ({}));
      if (!r.ok) { setErr(j.error || "Something went wrong. Please try again."); setBusy(false); return; }
      router.push(`/dashboard/mod-builder/${j.build.id}`);
    } catch {
      setErr("We couldn't reach Nxeon. Check your connection and try again.");
      setBusy(false);
    }
  }

