  const poll = useCallback(async () => {
    try {
      const r = await fetch(`/api/mod-builder/builds/${b.id}`, { cache: "no-store" });
      if (!r.ok) throw new Error(String(r.status));
      const j = await r.json();
      setB(j.build); setNetErr(false);
      return j.build as ModBuildView;
    } catch { setNetErr(true); return null; }
  }, [b.id]);

  useEffect(() => {
    if (!running) return;
    let stop = false;
    const tick = async () => {
      const nb = await poll();
      if (stop) return;
      if (nb && isTerminal(nb.status)) { router.refresh(); return; }
      setTimeout(tick, 2500);
    };
    const t = setTimeout(tick, 1500);
    return () => { stop = true; clearTimeout(t); };
  }, [running, poll, router]);

  const title = b.pluginName || (b.changeRequest ? "Updating your plugin" : running ? "Building your plugin" : "Your plugin");

  return (
    <div className="mb-root relative z-[1] mx-auto flex w-full max-w-[1280px] flex-col gap-5">
      <nav className="flex items-center gap-2 text-[12.5px] font-semibold text-tx-faint">
        <Link href="/dashboard/mod-builder" className="inline-flex items-center gap-1.5 hover:text-tx">
          <Icon name="cube" size={12} /> AI Mod Builder
        </Link>
        <span>/</span>
        <span className="truncate text-tx-mute">{b.pluginName || "Build"}</span>
        <span className="ml-auto"><PreviewBadge /></span>
      </nav>

      <header className="flex flex-col gap-3">
        <div className="flex flex-wrap items-center gap-3">
          <h1 className="text-[28px] font-extrabold leading-[1.1] tracking-[-0.03em] text-tx sm:text-[36px]">{title}</h1>
          <StatusPill status={b.status} />
        </div>
        <div className="flex flex-wrap items-center gap-2 text-[12px] font-semibold text-tx-faint">
          <span className="mb-who">Paper {b.mcVersion}</span>
          {b.version && <span className="mb-who">v{b.version}</span>}
          <span>Started {ago(b.createdAt)}</span>
          {b.finishedAt && <span>· took {dur(b.durationMs)}</span>}
        </div>
        <blockquote className="max-w-[90ch] rounded-xl border px-4 py-3 text-[13px] leading-[1.6] text-tx-body" style={{ borderColor: "var(--color-rim-hi)", background: "var(--color-well)" }}>
          {b.changeRequest ? (
            <>
              <span className="mb-1 block text-[10.5px] font-extrabold uppercase tracking-[0.14em] text-tx-faint">Change you asked for</span>
              {b.changeRequest}
            </>
          ) : (
            <>
              <span className="mb-1 block text-[10.5px] font-extrabold uppercase tracking-[0.14em] text-tx-faint">What you asked for</span>
              {b.prompt}
            </>
          )}
        </blockquote>
      </header>

      {running && <Progress b={b} netErr={netErr} />}
      {b.status === "succeeded" && (
        <Success b={b} servers={servers} onInstall={() => setModal("install")} onChange={() => setModal("change")} />
      )}
      {b.status === "failed" && <Failure b={b} />}

      {history.length > 1 && (
        <section className="card flex flex-col gap-3 p-4 sm:p-5">
          <h2 className="text-[14px] font-extrabold text-tx">Versions of this plugin</h2>
          <ol className="flex flex-col gap-1.5">
            {history.map((h, i) => (
              <li key={h.id}>
                <Link href={`/dashboard/mod-builder/${h.id}`}
                      className={`flex items-center gap-3 rounded-xl px-3 py-2 text-[12.5px] ${h.id === b.id ? "font-bold text-tx" : "text-tx-mute hover:text-tx"}`}
                      style={h.id === b.id ? { background: "color-mix(in srgb, var(--color-violet) 12%, transparent)" } : undefined}>
                  <span className="mb-who">{h.version ? `v${h.version}` : `#${i + 1}`}</span>
                  <span className="min-w-0 flex-1 truncate">{h.changeRequest || "First build"}</span>
                  <StatusPill status={h.status} />
                </Link>
              </li>
            ))}
          </ol>
        </section>
      )}

      {b.status !== "queued" && <BuildLog events={b.result?.events ?? []} open={running} />}

      {modal === "install" && <InstallModal build={b} servers={servers} onClose={() => setModal(null)} onDone={(nb) => { if (nb) setB(nb); router.refresh(); }} />}
      {modal === "change" && <ChangeModal build={b} onClose={() => setModal(null)} />}
    </div>
  );
}

// ── live progress ──────────────────────────────────────────────────────────
function Progress({ b, netErr }: { b: ModBuildView; netErr: boolean }) {
  const events = b.result?.events ?? [];
  const seen = new Set(events.map((e) => e.stage));
  const idx = ORDER.indexOf(b.status);
  const startedAt = events.find((e) => e.stage !== "queued")?.at;
  const [now, setNow] = useState(() => Date.now());
  useEffect(() => { const t = setInterval(() => setNow(Date.now()), 1000); return () => clearInterval(t); }, []);
  const elapsed = startedAt ? now - new Date(startedAt).getTime() : 0;
  const last = [...events].reverse().find((e) => e.message && e.stage !== "queued");
  const repairs = b.result?.repairs ?? 0;

  return (
    <section className="card flex flex-col gap-5 p-4 sm:p-6" aria-live="polite">
      <div className="flex flex-wrap items-center gap-3">
        <span className="text-[#8fd8ff]"><Spinner size={16} /></span>
        <span className="text-[15px] font-extrabold text-tx">
          {b.status === "queued"
            ? b.result?.queuePosition ? `In line, position ${b.result.queuePosition}` : "Waiting for a free builder"
            : last?.message || "Working on it"}
        </span>
        <span className="ml-auto text-[12.5px] font-bold tabular-nums text-tx-faint">{startedAt ? dur(elapsed) : ""}</span>
      </div>
      <div className="mb-bar"><i style={{ width: `${PCT[b.status] ?? 8}%` }} /></div>
      <ol className="mb-steps">
        {MB_STAGES.map((s) => {
          const si = ORDER.indexOf(s.key);
          let cls = "pending";
          if (s.key === b.status) cls = "now";
          else if (si < idx) cls = s.key === "repairing" && !seen.has("repairing") ? "skip" : "done";
          return (
            <li key={s.key} className={`mb-step ${cls}`}>
              <span className="mb-node">
                {cls === "done" ? <Icon name="check" size={13} tone="inherit" strokeWidth={2.6} /> : <StageIcon k={s.key} />}
              </span>
              <span className="flex flex-col gap-0.5 sm:items-center">
                <span className="mb-step-l">{s.label}</span>
                <span className="mb-step-s">
                  {cls === "skip" ? "Not needed" : s.key === "repairing" && repairs ? `Fix ${repairs} of 3` : s.sub}
                </span>
              </span>
            </li>
          );
        })}
      </ol>
      <p className="text-[12px] leading-[1.6] text-tx-faint">
        Most plugins take one to four minutes. You can leave this page. The build keeps going and shows up in your list when it&apos;s done.
        {netErr && <span className="ml-1 font-semibold text-[#ffcf7a]">Reconnecting…</span>}
      </p>
      <div>
        <button type="button" className="btn-ghost text-[12px]" onClick={async () => { await fetch(`/api/mod-builder/builds/${b.id}/cancel`, { method: "POST" }); }}>
          Cancel build
        </button>
      </div>
    </section>
  );
}

function StageIcon({ k }: { k: string }) {
  const name = { planning: "chatcode", coding: "pencil", compiling: "cpu", repairing: "refresh", scanning: "shieldcheck", succeeded: "cube" }[k] || "dotgrey";
  return <Icon name={name} size={13} tone="inherit" />;
}

