"use client";

import Link from "next/link";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useRouter } from "next/navigation";
import { Icon } from "@/components/nx/Icon";
import { MB_STAGES, isTerminal, type MbEvent, type ModBuildView } from "@/lib/modbuilder/types";
import type { MbServer } from "@/lib/modbuilder/install";
import { PreviewBadge, Spinner, StatusPill, ago, bytes, dur } from "./bits";
import { SourceViewer } from "./SourceViewer";
import { InstallModal, ChangeModal } from "./Modals";

type Hist = { id: string; status: string; version: string | null; changeRequest: string | null; createdAt: string };

const ORDER = ["queued", "planning", "coding", "compiling", "repairing", "scanning", "succeeded"];
const PCT: Record<string, number> = { queued: 4, planning: 12, coding: 38, compiling: 62, repairing: 72, scanning: 88, succeeded: 100, failed: 100 };

export function BuildView({ initial, servers, history }: { initial: ModBuildView; servers: MbServer[]; history: Hist[] }) {
  const router = useRouter();
  const [b, setB] = useState(initial);
  const [netErr, setNetErr] = useState(false);
  const [modal, setModal] = useState<null | "install" | "change">(null);
  const running = !isTerminal(b.status);

  const poll = useCallback(async () => {
    try {
      const r = await fetch(`/api/mod-builder/builds/${b.id}`, { cache: "no-store" });
      if (!r.ok) throw new Error(String(r.status));
      const j = await r.json();
      setB(j.build); setNetErr(false);
      return j.build as ModBuildView;
    } catch { setNetErr(true); return null; }
  }, [b.id]);

  useEffect(() => {
    if (!running) return;
    let stop = false;
    const tick = async () => {
      const nb = await poll();
      if (stop) return;
      if (nb && isTerminal(nb.status)) { router.refresh(); return; }
      setTimeout(tick, 2500);
    };
    const t = setTimeout(tick, 1500);
    return () => { stop = true; clearTimeout(t); };
  }, [running, poll, router]);

  const title = b.pluginName || (b.changeRequest ? "Updating your plugin" : running ? "Building your plugin" : "Your plugin");

  return (
    <div className="mb-root relative z-[1] mx-auto flex w-full max-w-[1280px] flex-col gap-5">
      <nav className="flex items-center gap-2 text-[12.5px] font-semibold text-tx-faint">
        <Link href="/dashboard/mod-builder" className="inline-flex items-center gap-1.5 hover:text-tx">
          <Icon name="cube" size={12} /> AI Mod Builder
        </Link>
        <span>/</span>
        <span className="truncate text-tx-mute">{b.pluginName || "Build"}</span>
        <span className="ml-auto"><PreviewBadge /></span>
      </nav>

      <header className="flex flex-col gap-3">
        <div className="flex flex-wrap items-center gap-3">
          <h1 className="text-[28px] font-extrabold leading-[1.1] tracking-[-0.03em] text-tx sm:text-[36px]">{title}</h1>
          <StatusPill status={b.status} />
        </div>
        <div className="flex flex-wrap items-center gap-2 text-[12px] font-semibold text-tx-faint">
          <span className="mb-who">Paper {b.mcVersion}</span>
          {b.version && <span className="mb-who">v{b.version}</span>}
          <span>Started {ago(b.createdAt)}</span>
          {b.finishedAt && <span>· took {dur(b.durationMs)}</span>}
        </div>
        <blockquote className="max-w-[90ch] rounded-xl border px-4 py-3 text-[13px] leading-[1.6] text-tx-body" style={{ borderColor: "var(--color-rim-hi)", background: "var(--color-well)" }}>
          {b.changeRequest ? (
            <>
              <span className="mb-1 block text-[10.5px] font-extrabold uppercase tracking-[0.14em] text-tx-faint">Change you asked for</span>
              {b.changeRequest}
            </>
          ) : (
            <>
              <span className="mb-1 block text-[10.5px] font-extrabold uppercase tracking-[0.14em] text-tx-faint">What you asked for</span>
              {b.prompt}
            </>
          )}
        </blockquote>
      </header>

      {running && <Progress b={b} netErr={netErr} />}
      {b.status === "succeeded" && (
        <Success b={b} servers={servers} onInstall={() => setModal("install")} onChange={() => setModal("change")} />
      )}
      {b.status === "failed" && <Failure b={b} />}

      {history.length > 1 && (
        <section className="card flex flex-col gap-3 p-4 sm:p-5">
          <h2 className="text-[14px] font-extrabold text-tx">Versions of this plugin</h2>
          <ol className="flex flex-col gap-1.5">
            {history.map((h, i) => (
              <li key={h.id}>
                <Link href={`/dashboard/mod-builder/${h.id}`}
                      className={`flex items-center gap-3 rounded-xl px-3 py-2 text-[12.5px] ${h.id === b.id ? "font-bold text-tx" : "text-tx-mute hover:text-tx"}`}
                      style={h.id === b.id ? { background: "color-mix(in srgb, var(--color-violet) 12%, transparent)" } : undefined}>
                  <span className="mb-who">{h.version ? `v${h.version}` : `#${i + 1}`}</span>
                  <span className="min-w-0 flex-1 truncate">{h.changeRequest || "First build"}</span>
                  <StatusPill status={h.status} />
                </Link>
              </li>
            ))}
          </ol>
        </section>
      )}

      {b.status !== "queued" && <BuildLog events={b.result?.events ?? []} open={running} />}

      {modal === "install" && <InstallModal build={b} servers={servers} onClose={() => setModal(null)} onDone={(nb) => { if (nb) setB(nb); router.refresh(); }} />}
      {modal === "change" && <ChangeModal build={b} onClose={() => setModal(null)} />}
    </div>
  );
}

// ── live progress ──────────────────────────────────────────────────────────
function Progress({ b, netErr }: { b: ModBuildView; netErr: boolean }) {
  const events = b.result?.events ?? [];
  const seen = new Set(events.map((e) => e.stage));
  const idx = ORDER.indexOf(b.status);
  const startedAt = events.find((e) => e.stage !== "queued")?.at;
  const [now, setNow] = useState(() => Date.now());
  useEffect(() => { const t = setInterval(() => setNow(Date.now()), 1000); return () => clearInterval(t); }, []);
  const elapsed = startedAt ? now - new Date(startedAt).getTime() : 0;
  const last = [...events].reverse().find((e) => e.message && e.stage !== "queued");
  const repairs = b.result?.repairs ?? 0;

  return (
    <section className="card flex flex-col gap-5 p-4 sm:p-6" aria-live="polite">
      <div className="flex flex-wrap items-center gap-3">
        <span className="text-[#8fd8ff]"><Spinner size={16} /></span>
        <span className="text-[15px] font-extrabold text-tx">
          {b.status === "queued"
            ? b.result?.queuePosition ? `In line, position ${b.result.queuePosition}` : "Waiting for a free builder"
            : last?.message || "Working on it"}
        </span>
        <span className="ml-auto text-[12.5px] font-bold tabular-nums text-tx-faint">{startedAt ? dur(elapsed) : ""}</span>
      </div>
      <div className="mb-bar"><i style={{ width: `${PCT[b.status] ?? 8}%` }} /></div>
      <ol className="mb-steps">
        {MB_STAGES.map((s) => {
          const si = ORDER.indexOf(s.key);
          let cls = "pending";
          if (s.key === b.status) cls = "now";
          else if (si < idx) cls = s.key === "repairing" && !seen.has("repairing") ? "skip" : "done";
          return (
            <li key={s.key} className={`mb-step ${cls}`}>
              <span className="mb-node">
                {cls === "done" ? <Icon name="check" size={13} tone="inherit" strokeWidth={2.6} /> : <StageIcon k={s.key} />}
              </span>
              <span className="flex flex-col gap-0.5 sm:items-center">
                <span className="mb-step-l">{s.label}</span>
                <span className="mb-step-s">
                  {cls === "skip" ? "Not needed" : s.key === "repairing" && repairs ? `Fix ${repairs} of 3` : s.sub}
                </span>
              </span>
            </li>
          );
        })}
      </ol>
      <p className="text-[12px] leading-[1.6] text-tx-faint">
        Most plugins take one to four minutes. You can leave this page. The build keeps going and shows up in your list when it&apos;s done.
        {netErr && <span className="ml-1 font-semibold text-[#ffcf7a]">Reconnecting…</span>}
      </p>
      <div>
        <button type="button" className="btn-ghost text-[12px]" onClick={async () => { await fetch(`/api/mod-builder/builds/${b.id}/cancel`, { method: "POST" }); }}>
          Cancel build
        </button>
      </div>
    </section>
  );
}

function StageIcon({ k }: { k: string }) {
  const name = { planning: "chatcode", coding: "pencil", compiling: "cpu", repairing: "refresh", scanning: "shieldcheck", succeeded: "cube" }[k] || "dotgrey";
  return <Icon name={name} size={13} tone="inherit" />;
}

// ── success ────────────────────────────────────────────────────────────────
function Success({ b, servers, onInstall, onChange }: { b: ModBuildView; servers: MbServer[]; onInstall: () => void; onChange: () => void }) {
  const r = b.result;
  const s = r?.summary;
  const okServers = servers.filter((x) => x.compatible);
  return (
    <>
      <section className="mb-success nx-dark-island flex flex-col gap-5 p-5 sm:p-7">
        <div className="flex flex-col gap-4 sm:flex-row sm:items-start">
          <span className="grid h-14 w-14 flex-none place-items-center rounded-2xl" style={{ background: "linear-gradient(140deg,#11c88e,#2f7eef 60%,#8c3ae9)", boxShadow: "0 14px 40px -14px rgba(17,200,142,.7)" }}>
            <Icon name="cube" size={22} tone="inherit" className="text-white" />
          </span>
          <div className="flex min-w-0 flex-col gap-1.5">
            <span className="text-[11px] font-extrabold uppercase tracking-[0.18em] text-[#4fe3b0]">Your plugin is ready</span>
            <h2 className="text-[21px] font-extrabold leading-[1.25] tracking-[-0.015em] text-white">{s?.tagline || `${b.pluginName} is built`}</h2>
            {s?.text && <p className="max-w-[80ch] text-[13.5px] leading-[1.65] text-[#c3d1f2]">{s.text}</p>}
            {s?.changes && <p className="text-[13px] leading-[1.6] text-[#8fd8ff]"><b>What changed:</b> {s.changes}</p>}
          </div>
        </div>
        <div className="flex flex-wrap gap-2.5">
          <a href={`/api/mod-builder/builds/${b.id}/jar`} className="mb-go" download>
            <Icon name="download" size={13} tone="inherit" /> Download .jar
          </a>
          <button type="button" className="mb-chip !px-4 !py-2.5 !text-[13px]" onClick={onInstall}>
            <Icon name="server" size={13} tone="inherit" /> Install to my server
          </button>
          <button type="button" className="mb-chip !px-4 !py-2.5 !text-[13px]" onClick={onChange}>
            <Icon name="pencil" size={13} tone="inherit" /> Ask for a change
          </button>
        </div>
        <div className="flex flex-wrap gap-x-5 gap-y-1.5 text-[12px] font-semibold text-[#8fa2d4]">
          <span>{b.jarName} · {bytes(b.jarSize)}</span>
          <span>Built in {dur(b.durationMs)}{b.attempts > 1 ? ` · fixed itself ${b.attempts - 1}×` : " · first try"}</span>
          {b.lastInstall && (
            <span className="text-[#4fe3b0]">
              Installed on {b.lastInstall.serverName} {ago(b.lastInstall.at)}{b.lastInstall.restarted ? " · restarted" : ""}
            </span>
          )}
          {!okServers.length && <span>No Paper server yet: download the .jar and drop it in your server&apos;s plugins folder.</span>}
        </div>
      </section>

      <div className="grid gap-5 lg:grid-cols-[minmax(0,1fr)_380px]">
        <div className="flex min-w-0 flex-col gap-5">
          {!!s?.howToUse?.length && (
            <section className="card flex flex-col gap-3 p-4 sm:p-5">
              <h3 className="text-[14.5px] font-extrabold text-tx">How to use it</h3>
              <ol className="flex flex-col gap-2.5">
                {s.howToUse.map((h, i) => (
                  <li key={i} className="flex gap-3 text-[13px] leading-[1.6] text-tx-body">
                    <span className="grid h-6 w-6 flex-none place-items-center rounded-full text-[11px] font-extrabold text-white" style={{ background: "linear-gradient(140deg,#14c5e4,#8c3ae9)" }}>{i + 1}</span>
                    <span className="pt-0.5">{h}</span>
                  </li>
                ))}
              </ol>
            </section>
          )}
          {!!r?.commands?.length && (
            <section className="card flex flex-col gap-2 p-4 sm:p-5">
              <h3 className="text-[14.5px] font-extrabold text-tx">Commands</h3>
              <div className="flex flex-col">
                {r.commands.map((c, i) => (
                  <div key={i} className="flex flex-col gap-1.5 border-t py-3 first:border-t-0 sm:flex-row sm:items-start sm:gap-4" style={{ borderColor: "var(--color-rim-soft)" }}>
                    <span className="sm:w-[38%]"><span className="mb-kbd">{c.usage}</span></span>
                    <span className="flex-1 text-[12.8px] leading-[1.55] text-tx-body">{c.description}</span>
                    <span className={`mb-who self-start ${/every/i.test(c.whoCanUse) ? "all" : ""}`}>{c.whoCanUse || (c.permission ? "With permission" : "Everyone")}</span>
                  </div>
                ))}
              </div>
            </section>
          )}
          {!!r?.config?.length && (
            <section className="card flex flex-col gap-2 p-4 sm:p-5">
              <h3 className="text-[14.5px] font-extrabold text-tx">Settings you can change</h3>
              <p className="text-[12px] text-tx-faint">In <span className="mb-kbd">plugins/{b.pluginName}/config.yml</span> on your server.</p>
              <div className="flex flex-col">
                {r.config.map((c, i) => (
                  <div key={i} className="grid gap-1 border-t py-2.5 first:border-t-0 sm:grid-cols-[38%_1fr_auto] sm:gap-4" style={{ borderColor: "var(--color-rim-soft)" }}>
                    <span className="text-[12.5px] font-bold text-tx" style={{ overflowWrap: "anywhere" }}>{c.key}</span>
                    <span className="text-[12.5px] leading-[1.5] text-tx-mute">{c.description}</span>
                    <span className="text-[12px] font-semibold text-tx-faint" style={{ overflowWrap: "anywhere" }}>{c.default ? `Default: ${c.default}` : ""}</span>
                  </div>
                ))}
              </div>
            </section>
          )}
        </div>

        <aside className="flex flex-col gap-5">
