              <h3 className="text-[14.5px] font-extrabold text-tx">Who can do what</h3>
              <p className="text-[12px] leading-[1.5] text-tx-faint">Permissions for LuckPerms or any permissions plugin.</p>
              {r.permissions.map((p, i) => (
                <div key={i} className="flex flex-col gap-1 border-t py-2.5 first:border-t-0" style={{ borderColor: "var(--color-rim-soft)" }}>
