          )}
          {!!s?.limitations?.length && (
            <section className="card flex flex-col gap-2 p-4 sm:p-5">
              <h3 className="flex items-center gap-2 text-[14px] font-extrabold text-tx"><Icon name="warncircle" size={13} tone="amber" /> Good to know</h3>
              <ul className="flex list-disc flex-col gap-1.5 pl-4 text-[12.5px] leading-[1.55] text-tx-mute">
                {s.limitations.map((l, i) => <li key={i}>{l}</li>)}
