}

function Safety({ b }: { b: ModBuildView }) {
  const sf = b.result?.safety;
  const warns = (sf?.findings ?? []).filter((f) => f.severity === "warn");
  const checks = [
    ["No internet access", "It can't send your data anywhere."],
    ["Can't run programs", "Nothing outside Minecraft gets started."],
    ["Only its own folder", "Reads and writes only plugins/" + (b.pluginName || "") + "."],
    ["No hidden admin access", "No secret players with special powers."],
  ];
  return (
    <section className="card flex flex-col gap-3 p-4 sm:p-5">
      <div className="flex items-center gap-2">
        <Icon name="shieldcheck" size={15} tone="mint" />
        <h3 className="text-[14.5px] font-extrabold text-tx">Safety check</h3>
        <span className={`mb-pill ml-auto ${warns.length ? "warn" : "ok"}`}><span className="dot" />{warns.length ? "Passed with notes" : "Passed"}</span>
      </div>
      <div className="flex flex-col gap-2.5">
        {checks.map(([t, d]) => (
          <div key={t} className="mb-check">
            <Icon name="checkcircle" size={13} tone="mint" />
            <span className="flex flex-col"><span className="font-bold text-tx">{t}</span><span className="text-[11.5px] font-medium text-tx-faint">{d}</span></span>
          </div>
        ))}
      </div>
      {warns.length > 0 && (
        <div className="rounded-xl border px-3 py-2.5 text-[12px] leading-[1.55] text-tx-mute" style={{ borderColor: "rgba(255,180,60,.3)", background: "rgba(255,180,60,.06)" }}>
          <b className="text-tx">Notes:</b> this plugin {Array.from(new Set(warns.map((w) => w.message))).join("; ")}. That&apos;s allowed, just worth knowing.
        </div>
      )}
      <p className="text-[11px] leading-[1.5] text-tx-faint">Automated scan of the compiled code. It checks for risky behaviour; it doesn&apos;t guarantee the plugin is bug-free.</p>
    </section>
  );
}

// ── failure ────────────────────────────────────────────────────────────────
const TIPS: Record<string, string[]> = {
  compile: ["Describe fewer features at once. You can add more with “Ask for a change” afterwards.", "Avoid asking for other plugins (like Vault or WorldEdit). Builds use plain Paper only."],
  safety: ["Remove anything that needs the internet, other programs or files outside the server.", "Webhooks, Discord bots and remote databases can't be built yet."],
  refused: ["We only build plugins that are safe for your players and your server."],
  budget: ["Split a big idea into two or three smaller plugins."],
  timeout: ["Split a big idea into two or three smaller plugins."],
};

function Failure({ b }: { b: ModBuildView }) {
  const router = useRouter();
  const [text, setText] = useState(b.changeRequest || b.prompt);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const [showTech, setShowTech] = useState(false);
  const tips = TIPS[b.errorCode || ""] ?? ["This one is on us. Trying again usually works."];
  const canRetry = b.errorCode !== "refused";

  async function retry(prompt: string) {
    setBusy(true); setErr(null);
    const body = b.changeRequest && b.baseBuildId
      ? { baseBuildId: b.baseBuildId, changeRequest: prompt }
      : { prompt, mcVersion: b.mcVersion };
    const r = await fetch("/api/mod-builder/builds", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) });
    const j = await r.json().catch(() => ({}));
    if (!r.ok) { setErr(j.error || "Couldn't start the build."); setBusy(false); return; }
    router.push(`/dashboard/mod-builder/${j.build.id}`);
  }

  return (
    <section className="mb-failure nx-dark-island flex flex-col gap-4 p-5 sm:p-7">
      <div className="flex gap-4">
        <span className="grid h-12 w-12 flex-none place-items-center rounded-2xl" style={{ background: "rgba(255,90,120,.14)", border: "1px solid rgba(255,90,120,.35)" }}>
          <Icon name={b.errorCode === "refused" || b.errorCode === "safety" ? "shield" : "warncircle"} size={18} tone="rose" />
        </span>
        <div className="flex flex-col gap-1.5">
          <span className="text-[11px] font-extrabold uppercase tracking-[0.18em] text-[#ff9fb3]">
            {b.errorCode === "cancelled" ? "Cancelled" : b.errorCode === "refused" ? "We can't build this" : "This build didn't work"}
          </span>
          <p className="text-[15px] font-bold leading-[1.5] text-white">{b.error || "Something went wrong."}</p>
          <ul className="mt-1 flex list-disc flex-col gap-1 pl-4 text-[12.8px] leading-[1.55] text-[#c3d1f2]">
            {tips.map((t) => <li key={t}>{t}</li>)}
          </ul>
          <p className="text-[12px] text-[#8fa2d4]">Failed builds don&apos;t count against you.</p>
        </div>
      </div>
      {canRetry && (
        <div className="flex flex-col gap-2.5">
          <label className="text-[12px] font-bold text-[#a9b9e3]" htmlFor="mb-rephrase">Reword it and try again</label>
          <textarea id="mb-rephrase" value={text} onChange={(e) => setText(e.target.value)} rows={4}
                    className="w-full rounded-2xl border bg-[rgba(6,13,34,.85)] p-3.5 text-[13.5px] leading-[1.55] text-white outline-none"
                    style={{ borderColor: "rgba(150,175,255,.22)" }} />
          <div className="flex flex-wrap gap-2.5">
            <button type="button" className="mb-go" disabled={busy || text.trim().length < 4} onClick={() => retry(text)}>
              {busy ? <Spinner /> : <Icon name="refresh" size={13} tone="inherit" />} {text.trim() === (b.changeRequest || b.prompt).trim() ? "Try again" : "Build with my changes"}
            </button>
            <Link href="/dashboard/mod-builder" className="mb-chip !px-4 !py-2.5">Start something new</Link>
          </div>
          {err && <p className="text-[12.5px] font-semibold text-[#ff9fb3]">{err}</p>}
        </div>
      )}
      {b.result?.errorDetail && (
        <div>
          <button type="button" className="text-[12px] font-bold text-[#8fa2d4] hover:text-white" onClick={() => setShowTech((v) => !v)}>
            {showTech ? "Hide" : "Show"} technical details
          </button>
          {showTech && <pre className="mt-2 max-h-[300px] overflow-auto whitespace-pre-wrap rounded-xl bg-[#020615] p-3 text-[11.5px] leading-[1.5] text-[#aab8de]">{b.result.errorDetail}</pre>}
        </div>
      )}
    </section>
  );
}

// ── build log ──────────────────────────────────────────────────────────────
function BuildLog({ events, open }: { events: MbEvent[]; open: boolean }) {
  const [show, setShow] = useState(open);
  const [detail, setDetail] = useState<number | null>(null);
  const endRef = useRef<HTMLLIElement>(null);
  const list = useMemo(() => events.filter((e) => e.stage !== "queued" || events.length < 3), [events]);
  const t0 = list[0] ? new Date(list[0].at).getTime() : 0;
  useEffect(() => { if (open && show) endRef.current?.scrollIntoView({ block: "nearest" }); }, [list.length, open, show]);
  if (!list.length) return null;
  return (
    <section className="card flex flex-col gap-2 p-4 sm:p-5">
      <button type="button" className="flex items-center gap-2 text-left" onClick={() => setShow((v) => !v)}>
        <Icon name="activity" size={13} tone="cyan" />
        <h3 className="text-[14px] font-extrabold text-tx">Build activity</h3>
        <span className="text-[12px] text-tx-faint">{list.length} steps</span>
        <span className="ml-auto text-[12px] font-bold text-tx-faint">{show ? "Hide" : "Show"}</span>
      </button>
      {show && (
        <ol className="mb-log max-h-[340px] overflow-auto pr-1">
          {list.map((e, i) => (
            <li key={i} ref={i === list.length - 1 ? endRef : undefined}>
              <time>+{dur(new Date(e.at).getTime() - t0)}</time>
              <Icon name={e.stage === "failed" ? "xcircle" : e.stage === "succeeded" ? "checkcircle" : e.stage === "repairing" ? "refresh" : "dotgrey"} size={10}
                    tone={e.stage === "failed" ? "rose" : e.stage === "succeeded" ? "mint" : e.stage === "repairing" ? "amber" : "slate"} />
              <span className="min-w-0 text-tx-body">
                {e.message}
                {e.detail && (
                  <>
                    {" "}<button type="button" className="text-[11.5px] font-bold text-tx-faint hover:text-tx" onClick={() => setDetail(detail === i ? null : i)}>{detail === i ? "hide" : "details"}</button>
                    {detail === i && <pre className="mt-1.5 max-h-[220px] overflow-auto whitespace-pre-wrap rounded-lg p-2.5 text-[11px] leading-[1.5] text-tx-mute" style={{ background: "var(--color-well)" }}>{e.detail}</pre>}
                  </>
                )}
              </span>
            </li>
          ))}
        </ol>
      )}
    </section>
  );
}

