"use client";

import Link from "next/link";
import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import { Icon } from "@/components/nx/Icon";
import type { ModBuildView } from "@/lib/modbuilder/types";
import type { MbServer } from "@/lib/modbuilder/install";
import { Spinner } from "./bits";

function Modal({ title, sub, onClose, children }: { title: string; sub?: string; onClose: () => void; children: React.ReactNode }) {
  useEffect(() => {
    const k = (e: KeyboardEvent) => { if (e.key === "Escape") onClose(); };
    window.addEventListener("keydown", k);
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => { window.removeEventListener("keydown", k); document.body.style.overflow = prev; };
  }, [onClose]);
  return (
    <div className="mb-modal-back" role="dialog" aria-modal="true" aria-label={title} onMouseDown={(e) => { if (e.target === e.currentTarget) onClose(); }}>
      <div className="mb-modal card flex flex-col gap-4 p-5 sm:p-6">
        <div className="flex items-start gap-3">
          <div className="flex flex-col gap-1">
            <h2 className="text-[18px] font-extrabold tracking-[-0.01em] text-tx">{title}</h2>
            {sub && <p className="text-[12.5px] leading-[1.55] text-tx-faint">{sub}</p>}
          </div>
          <button type="button" className="ml-auto rounded-lg p-1.5 text-tx-faint hover:text-tx" onClick={onClose} aria-label="Close">
            <Icon name="xcircle" size={14} tone="inherit" />
          </button>
        </div>
        {children}
      </div>
    </div>
  );
}

export function InstallModal({ build, servers, onClose, onDone }: { build: ModBuildView; servers: MbServer[]; onClose: () => void; onDone: (b?: ModBuildView) => void }) {
  const firstOk = servers.find((s) => s.compatible);
  const [sel, setSel] = useState<string | null>(build.lastInstall?.serverId && servers.some((s) => s.id === build.lastInstall!.serverId && s.compatible) ? build.lastInstall.serverId : firstOk?.id ?? null);
  const chosen = servers.find((s) => s.id === sel);
  const [restart, setRestart] = useState(true);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const [done, setDone] = useState<null | { replaced: string[]; restarted: boolean; restartNote: string | null; path: string }>(null);

  async function go() {
    if (!sel) return;
    setBusy(true); setErr(null);
    try {
      const r = await fetch(`/api/mod-builder/builds/${build.id}/install`, {
        method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ serverId: sel, restart: restart && chosen?.status === "RUNNING" }),
      });
      const j = await r.json().catch(() => ({}));
      if (!r.ok) { setErr(j.error || "The install didn't go through."); setBusy(false); return; }
      setDone(j); setBusy(false); onDone();
    } catch { setErr("We couldn't reach Nxeon. Try again."); setBusy(false); }
  }

  if (done) {
    return (
      <Modal title="Installed" onClose={onClose}>
        <div className="flex flex-col items-center gap-3 py-2 text-center">
          <span className="grid h-14 w-14 place-items-center rounded-full" style={{ background: "rgba(17,200,142,.14)", border: "1px solid rgba(17,200,142,.4)" }}>
            <Icon name="checkcircle" size={22} tone="mint" />
          </span>
          <p className="text-[14px] font-bold text-tx">{build.jarName} is on {chosen?.name}.</p>
          <p className="max-w-[46ch] text-[12.5px] leading-[1.6] text-tx-mute">
            {done.restarted ? "The server is restarting now. Your plugin loads as soon as it's back up (usually under a minute)."
              : done.restartNote ? `We couldn't restart it automatically: ${done.restartNote} Restart it from the server page to load the plugin.`
              : "Restart the server to load the plugin. Paper doesn't load new plugins while it's running."}
            {done.replaced.length > 0 && ` We replaced ${done.replaced.join(", ")} and kept a backup of it.`}
          </p>
          <div className="mt-1 flex flex-wrap justify-center gap-2.5">
            <Link href={`/dashboard/servers/${sel}`} className="mb-go">Open server <Icon name="external" size={12} tone="inherit" /></Link>
            <button type="button" className="btn-secondary" onClick={onClose}>Done</button>
          </div>
        </div>
      </Modal>
    );
  }

  return (
    <Modal title="Install to my server" sub={`Copies ${build.jarName} into the server's plugins folder.`} onClose={onClose}>
      {servers.length === 0 ? (
        <div className="flex flex-col items-center gap-3 py-4 text-center">
          <Icon name="gamepad" size={22} tone="violet" />
          <p className="text-[13px] font-bold text-tx">You don&apos;t have a Minecraft server yet</p>
          <p className="max-w-[40ch] text-[12.5px] leading-[1.55] text-tx-faint">Download the .jar and put it in any Paper server&apos;s plugins folder, or start a Paper server on Nxeon.</p>
          <Link href="/deploy?type=game" className="mb-go">Get a Minecraft server</Link>
        </div>
      ) : (
        <>
          <div className="flex flex-col gap-2" role="radiogroup" aria-label="Server">
            {servers.map((s) => (
              <label key={s.id} className={`mb-opt ${sel === s.id ? "on" : ""} ${s.compatible ? "" : "off"}`}>
                <input type="radio" name="mb-srv" className="sr-only" disabled={!s.compatible} checked={sel === s.id} onChange={() => setSel(s.id)} />
                <span className="mb-tile" style={{ width: 34, height: 34, borderRadius: 10 }}><Icon name="gamepad" size={13} tone={s.compatible ? "violet" : "slate"} /></span>
                <span className="flex min-w-0 flex-1 flex-col">
                  <span className="truncate text-[13px] font-bold text-tx">{s.name}</span>
                  <span className="text-[11.5px] text-tx-faint">{s.compatible ? `${cap(s.variant)} · ${s.status === "RUNNING" ? "online" : "stopped"}` : s.reason}</span>
                </span>
                {sel === s.id && <Icon name="checkcircle" size={14} tone="violet" />}
              </label>
            ))}
          </div>
          {chosen?.status === "RUNNING" && (
            <label className="flex cursor-pointer items-start gap-2.5 text-[12.8px] leading-[1.5] text-tx-body">
              <input type="checkbox" className="mt-0.5" checked={restart} onChange={(e) => setRestart(e.target.checked)} />
              <span><b className="text-tx">Restart the server now</b> so the plugin loads. Players get a short warning first.</span>
            </label>
          )}
          <p className="flex items-start gap-2 text-[12px] leading-[1.55] text-tx-faint">
            <Icon name="archive" size={12} tone="cyan" className="mt-0.5 flex-none" />
            If an older version of {build.pluginName} is already there, we back it up before replacing it.
          </p>
          {err && <p role="alert" className="text-[12.5px] font-semibold text-[#ff8fa6]">{err}</p>}
          <div className="flex justify-end gap-2.5">
            <button type="button" className="btn-secondary" onClick={onClose}>Cancel</button>
            <button type="button" className="mb-go" disabled={!sel || busy} onClick={go}>
              {busy ? <Spinner /> : <Icon name="upload" size={13} tone="inherit" />} {busy ? "Installing…" : "Install"}
            </button>
          </div>
        </>
      )}
    </Modal>
  );
}

const CHANGE_IDEAS = ["Make the messages more colourful", "Add a reload command", "Let operators change the numbers in game", "Add a cooldown"];

export function ChangeModal({ build, onClose }: { build: ModBuildView; onClose: () => void }) {
  const router = useRouter();
  const [text, setText] = useState("");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);

  async function go() {
    setBusy(true); setErr(null);
    const r = await fetch("/api/mod-builder/builds", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ baseBuildId: build.id, changeRequest: text.trim() }) });
    const j = await r.json().catch(() => ({}));
