  const user = await db.user.create({ data: { email, passwordHash: "x", name: "Mods Tester", emailVerifiedAt: new Date(), heardAboutUs: "other" } as never });
  const plan = await db.plan.upsert({ where: { slug: "agt-base" }, update: {}, create: { slug: "agt-base", name: "Base", cpuCores: 2, ramMB: 4096, diskGB: 30, priceCents: 500 } });
  const tpl = await db.osTemplate.upsert({ where: { slug: "agt-minecraft" }, update: {}, create: { slug: "agt-minecraft", name: "Minecraft", category: "APPLICATION", family: "minecraft", vmid: 9000, setupScript: "docker run -d --name mc itzg/minecraft-server" } });
  const gp = await db.gamePlan.upsert({ where: { id: "agt-gp4" }, update: {}, create: { id: "agt-gp4", name: "Minecraft — 4 GB", gameFamily: "minecraft", ramMB: 4096, cpuCores: 2, diskGB: 30, slots: 20, priceCents: 1294, basePlanId: plan.id } as never });
  const mk = (hostname: string, variant: string) => db.server.create({ data: { name: hostname, hostname, userId: user.id, planId: plan.id, osTemplateId: tpl.id, gamePlanId: gp.id, status: "RUNNING", gameVariant: variant, gameConfig: { VERSION: "1.21.1" }, ipAddress: hostname === "agt-fabric" ? "10.99.0.5" : "10.99.0.6" } as never });
  await db.server.deleteMany({ where: { hostname: { in: ["agt-fabric", "agt-paper"] } } });
  const fab = await mk("agt-fabric", "fabric");
  const pap = await mk("agt-paper", "paper");
  const mod = (slug: string, name: string, category: string, categories: string[], loaders: string[], fileBytes: number, source = "modrinth") =>
    db.gameMod.upsert({ where: { gameFamily_slug: { gameFamily: "minecraft", slug } }, update: {}, create: { gameFamily: "minecraft", slug, name, category, categories, loaders, gameVersions: ["1.21.1"], source, sourceId: slug, fileBytes, downloads: 1000000, description: `${name} for testing`, serverSide: "required" } });
  const m = {
    fapi: await mod("fabric-api", "Fabric API", "Mods", ["library"], ["fabric"], 2_300_000),
    lith: await mod("lithium", "Lithium", "Mods", ["optimization"], ["fabric"], 720_000),
    create: await mod("create-fabric", "Create Fabric", "Mods", ["technology", "decoration"], ["fabric"], 18_400_000),
    balm: await mod("balm", "Balm", "Mods", ["library"], ["fabric"], 480_000),
    way: await mod("waystones", "Waystones", "Mods", ["transportation", "adventure"], ["fabric"], 1_200_000),
    terra: await mod("terralith", "Terralith", "Mods", ["worldgen"], ["fabric", "datapack"], 9_100_000),
    fo: await mod("fabulously-optimized", "Fabulously Optimized", "Modpacks", [], ["mrpack"], 52_000),
    lp: await mod("luckperms", "LuckPerms", "Plugins", ["management"], ["paper"], 1_500_000),
    ess: await mod("essentialsx", "EssentialsX", "Plugins", ["utility"], ["paper"], 1_100_000, "spigotmc"),
    vault: await mod("vault", "Vault", "Plugins", ["library"], ["paper"], 120_000, "spigotmc"),
    worldedit: await mod("worldedit", "WorldEdit", "Plugins", ["utility"], ["paper"], 3_400_000),
  };
  const sm = (serverId: string, modId: string, status: string, version: string, extra: Record<string, unknown> = {}) => db.serverMod.create({ data: { serverId, modId, status, version, ...extra } });
  await sm(fab.id, m.fapi.id, "INSTALLED", "0.102.0+1.21.1");
  await sm(fab.id, m.lith.id, "INSTALLED", "0.13.0", { availableVersion: "0.13.1" });
  await sm(fab.id, m.create.id, "INSTALLED", "0.5.1-j");
  await sm(fab.id, m.balm.id, "INSTALLED", "21.0.20");
  await sm(fab.id, m.way.id, "DISABLED", "21.1.4");
  await sm(fab.id, m.terra.id, "FAILED", "", { error: "Terralith 2.5.5 has no build for Fabric 1.21.1 — nothing was installed." });
  await sm(fab.id, m.fo.id, "INSTALLED", "6.2.0");
  await db.job.create({ data: { type: "GAME_MOD_SYNC", serverId: fab.id, status: "DONE", progress: 100, payload: { op: "install", modId: m.create.id, result: { restartRequired: false, changed: [], failed: [], deps: { [m.fapi.id]: [], [m.lith.id]: [], [m.create.id]: [m.fapi.id], [m.balm.id]: [], [m.way.id]: [m.balm.id], [m.fo.id]: [m.fapi.id] } } } } as never });
  await db.job.create({ data: { type: "GAME_BACKUP", serverId: fab.id, status: "DONE", progress: 100, payload: {} } as never });

  await sm(pap.id, m.lp.id, "INSTALLED", "5.4.141");
  await sm(pap.id, m.vault.id, "INSTALLED", "1.7.3");
  await sm(pap.id, m.ess.id, "INSTALLED", "2.20.1");
  await sm(pap.id, m.worldedit.id, "DISABLED", "7.3.6");
  await db.job.create({ data: { type: "GAME_MOD_SYNC", serverId: pap.id, status: "DONE", progress: 100, payload: { op: "disable", modId: m.worldedit.id, result: { restartRequired: true, changed: ["disabled WorldEdit"], failed: [], deps: { [m.lp.id]: [], [m.vault.id]: [], [m.ess.id]: [m.vault.id], [m.worldedit.id]: [] } } } } as never });
  await db.modUpdateRun.create({ data: { serverId: pap.id, trigger: "health", status: "HEALTH_WARN", summary: "x", plan: { startedAt: new Date().toISOString(), verdicts: [{ name: "LuckPerms", status: "loaded", evidence: "[LuckPerms] Enabling" }, { name: "Vault", status: "loaded", evidence: "[Vault] Enabling" }, { name: "EssentialsX", status: "error", evidence: "Error occurred while enabling EssentialsX v2.20.1" }] }, finishedAt: new Date() } as never });

  const token = await new SignJWT({ sub: user.id, sv: 0, typ: "session" }).setProtectedHeader({ alg: "HS256" }).setIssuedAt().setExpirationTime("2d").sign(new TextEncoder().encode(process.env.AUTH_SECRET!));
  await db.userSession.create({ data: { userId: user.id, tokenHash: createHash("sha256").update(token).digest("hex") } });
  console.log(JSON.stringify({ token, cookie: process.env.NXEON_COOKIE_NAME ?? "nxeon_session", fab: fab.id, pap: pap.id }));
  await db.$disconnect();
}
main().catch((e) => { console.error(e); process.exit(1); });
