const mineflayer = require("mineflayer");
const { Rcon } = require("rcon-client");
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
(async () => {
  const rcon = await Rcon.connect({ host: "127.0.0.1", port: 25575, password: "papertest-local" });
  const bot = mineflayer.createBot({ host: "127.0.0.1", port: 25565, username: "Tester3", version: "1.21.11", auth: "offline" });
  const chat = []; const out = [];
  bot.on("messagestr", (m) => chat.push(m));
  bot.on("title", (t) => chat.push("[title] " + JSON.stringify(t).slice(0, 140)));
  bot.on("bossBarCreated", (b) => chat.push("[bossbar] " + JSON.stringify(b.title).slice(0, 140) + " health=" + b.health));
  await new Promise((r) => bot.once("spawn", r)); await sleep(2500);
  out.push({ step: "join (daily reward)", chat: chat.splice(0), bread: bot.inventory.items().filter((i) => i.name === "bread").reduce((a, i) => a + i.count, 0) });
  await rcon.send("op Tester3"); await sleep(400);
  for (const c of ["/streak", "/summonboss"]) { bot.chat(c); await sleep(2500); out.push({ cmd: c, chat: chat.splice(0) }); }
  const ents = Object.values(bot.entities).filter((e) => e.name === "wither_skeleton").map((e) => ({ name: e.name, custom: e.metadata && JSON.stringify(e.metadata[2] ?? "").slice(0, 120) }));
  out.push({ step: "entities", witherSkeletons: ents });
  await rcon.send("kill @e[type=minecraft:wither_skeleton]"); await sleep(1500);
  out.push({ step: "after kill", chat: chat.splice(0) });
  console.log(JSON.stringify(out, null, 1)); bot.quit(); await rcon.end(); process.exit(0);
})().catch((e) => { console.error("FAILED", e); process.exit(1); });
EOF
