cd /tank/nxeon-wt-modbuilder && ls test | head -3; cat > test/modbuilder-gate.test.ts <<'EOF'
import { describe, it, expect } from "vitest";
import { readFileSync, readdirSync, statSync } from "node:fs";
import { join } from "node:path";
import { emailAllowed, parsePreviewEmails, PREVIEW_ACCESS_DEFAULT } from "@/lib/preview-access";

describe("preview-access", () => {
  it("parses a comma list, case-insensitively", () => {
    expect(parsePreviewEmails(" A@x.com, b@y.com ,,")).toEqual(["a@x.com", "b@y.com"]);
    expect(emailAllowed("A@X.COM", parsePreviewEmails("a@x.com"))).toBe(true);
    expect(emailAllowed("c@x.com", parsePreviewEmails("a@x.com"))).toBe(false);
    expect(emailAllowed("", parsePreviewEmails(""))).toBe(false);
  });
  it("defaults to the owner only", () => {
    expect(parsePreviewEmails(PREVIEW_ACCESS_DEFAULT)).toEqual(["nicholas.sj.albanese@gmail.com"]);
  });
});

function files(dir: string): string[] {
  return readdirSync(dir).flatMap((n) => {
    const p = join(dir, n);
    return statSync(p).isDirectory() ? files(p) : [p];
  });
}

describe("every Mod Builder surface is gated", () => {
  it("pages call requireModBuilderUser", () => {
    for (const f of files("app/dashboard/mod-builder").filter((f) => f.endsWith("page.tsx"))) {
      expect(readFileSync(f, "utf8"), f).toMatch(/requireModBuilderUser\(\)/);
    }
  });
  it("API routes resolve the preview user", () => {
    for (const f of files("app/api/mod-builder").filter((f) => f.endsWith("route.ts"))) {
      expect(readFileSync(f, "utf8"), f).toMatch(/ownedBuild\(|modBuilderUser\(\)/);
    }
  });
  it("admin page checks the preview allowlist", () => {
    expect(readFileSync("app/admin/mod-builder/page.tsx", "utf8")).toMatch(/isPreviewUser\(/);
  });
  it("the static nav never lists it", () => {
    expect(readFileSync("lib/nx/nav.ts", "utf8")).not.toMatch(/mod-builder/);
  });
});
EOF
nice npx vitest run test/modbuilder-gate.test.ts 2>&1 | tail -6

